import { controlHelpText } from "./controlHelpContent";
import type { Language } from "./i18n";
import type { HelpTopic } from "./helpTopics";

export const helpText: Record<Language, Record<HelpTopic, string>> = {
  en: {
    ...controlHelpText.en,
    terminalShortcuts: "The focused shell receives your keystrokes, including the shortcut you configured for Copy. The shell decides what the keystroke does, so it never starts a file copy while the shell has focus. Click a file pane to use file shortcuts again. If the panes are hidden, click Terminal to return to files. [[terminal|Terminal help]] covers shell commands and history.",
    archives: "Packaged Dirlume includes 7-Zip for offline archive operations. Select local files or folders and press Shift+F1, then choose the format, destination, and compression options. Press Enter on the archive to browse it in the [[files|file pane]]. Use F5 to extract selected items. To copy or move local items into a writable ZIP or 7z folder, use F5 or F6 in the other pane and confirm the archive and member path. Browse an archive in List or Tree. In a writable ZIP or 7z archive, F7 creates a folder, Shift+F4 creates a text file, and Files → Rename renames the selected entry. In Tree, new entries go into the selected folder or the selected file’s parent. A writable archive supports text editing with F4, moving entries to a local folder or a writable archive folder with F6, and removing entries with F8. A move removes the archive entry only after the local copy completes. Encrypted and split archives are read-only. Archive profiles remember options without passwords. To recover a file removed after archiving, copy it from Trash to the desired folder. The system Restore command may point to the temporary folder used to verify it.",
    files: "Browse folders independently in the two panes. On Ubuntu, press Enter on a local executable .sh file to run it in the embedded Terminal from the script’s folder. Open is configurable in Options → Keyboard shortcuts. Double-click or use Open in system for the usual file-opening behavior. Click a breadcrumb to open that folder. Dimmed breadcrumbs return to descendant folders in the same branch. Click the empty area of the address field to type a path. Use Insert, Shift with the arrow keys, or Ctrl-click to [[operations|mark multiple items]]. Drag the divider to resize the panes. Choose a mode from Left or Right, or use Left Ctrl with a top-row digit. Press 1 for Brief, 2 for Medium, 3 for Full, 4 for Wide, 8 for File owners, 9 for File links, or 0 for Alternative full. Edit list and status fields in Options → Panel modes. Press Ctrl+F12 to open Sort by for the active pane or choose Sort modes from Left or Right. Press + for ascending, − for descending, * to reverse, or F4 to change tie-breakers. Define ordered filename masks under Options → Sort groups. Right-click the headings to choose which columns to show for the current pane and mode. Under Options → Main File Panels, change hidden-file visibility, [[panels|panel colors]], and each pane's font size. Ctrl+Shift+0–9 adds the current folder to a bookmark group and Right Ctrl+0–9 opens that group. Use Commands → Folder shortcuts to manage saved groups. Choose Standard, Twin panels, or Classic commander under Panel layout. Twin panels adds drive buttons with icons, the free space of the drive above each list, and a flat key bar. Classic commander uses dense rows, a drive bar above each pane, details of the current item at the bottom, and a function-key bar.\n\nWhen you open a local file through its system association, the pane shows the request while it is pending, then confirms that it was sent or reports the error. Look up the path and result in [[terminal|Terminal → File opens]].\n\nOpen the file menu on a single eligible file and choose the Git submenu. It offers Show history, Show blame, Compare with revision, and Show diff when available for that file. Show diff lists staged and unstaged changes separately. Closing Git View returns to the file. The shortcut can be changed under Options → Keyboard shortcuts.",
    operations: "Mark the items you want to work with, or use the current row. Copy or move opens a destination dialog, normally prefilled from the [[files|other pane]]. When F6 opens the move dialog with a destination, Move has focus. Press Enter to move to that destination or use Tab or Shift+Tab to reach the path field and edit it. Read the progress and choose how to handle existing files or folders when prompted. Drag marked items into the other local pane to copy them or select Move instead of copying. The system clipboard can also carry local files to and from other applications.\n\nThe file-action bar opens Viewer, Editor, Copy, Rename or move, New file, New folder, Trash, Compare, marking, and Terminal according to the active layout and source. A disabled button means its command cannot run for the current item or view. In a file pane, a short right-click opens Dirlume’s item menu when Right-click selection is off. To open the Windows Shell menu for a local item, hold the right button for half a second and release when the indicator appears. Holding opens Dirlume’s menu on Ubuntu or for a source without a system menu. The Open file context menu shortcut, Shift+F10 by default, opens Dirlume’s menu for the focused row. A marked row offers batch actions and their item counts. An unmarked row targets that item and keeps the existing marks. The same shortcuts and dialogs work in [[search|local Search results]] for Copy, Move, Trash, and permanent deletion. See [[actionDialogs|file operation dialogs]].\n\nWhen Copy or Move encounters an existing folder, it continues into that folder and preserves entries found only at the destination. In Ask mode, file collisions prompt individually. Overwrite all applies to all overwritable files in that transfer. If Also ask about read-only files is enabled, Remember choice for read-only files applies only to those files. Ordinary remembered choices leave the separate read-only confirmation in place. In Collections, F5 adds references when the other pane shows a collection folder. F5 from a collection copies the selected originals. Remove from collection removes references or virtual folders.\n\nFor one selected item, F6 accepts a new name in the destination field and renames the item in its current folder. The other pane supplies the initial value. Enter the actual destination path to move the item to a local folder or a supported connected source. Google Drive paths include the connected account followed by :/My Drive and the folder path.",
    search: "In a file pane, hold Alt and type a letter to open Quick search. It matches anywhere in the visible file and folder names and shows names that start with the query first. Use Up and Down to cycle through the matches. Click the match count, or press Tab and Enter to open the results table. Choose a row to move the cursor to that item and return to the pane. In the search field, Enter opens the current match and Esc returns to the pane. Change or disable Quick search by name in Options → Keyboard shortcuts. To search subfolders, open Find files and enter a mask such as *.md. Choose Show in panel to put the results in a [[files|file pane]], or Go to selected file to open its containing folder.\n\nThe location under Folder and subfolders shows the search root. In the file mask, * matches any number of characters and ? matches one character. Stop retains results already found, and the status shows partial results when part of the search could not finish. Go to file reveals the current result and Show in panel keeps the list open in a file pane. Close dismisses the search.\n\nIn local Search results, use Copy, Move, Move to Trash, or Delete permanently on marked files or on the current file. Successfully moved or removed paths disappear from the results. Refresh reruns the search with the original folder, mask, and hidden-file setting. The pane stays open even with zero matches. See [[paneFilter|Filter folder]] for filtering only the current list.",
    viewer: "Use F3 to view a file, or to measure a selected folder. On the parent row (..), F3 and the Measure button total the visible immediate child folders, including unmarked ones. In Tree, expanded descendants count toward their top-level folders. This leaves Folder sizes as set. Escape cancels the remaining work and keeps completed totals. Open the diagnostic viewer with Help → Open error log. In its File menu, choose Clear error log and confirm to remove the saved entries. Text files over 8 MiB open in pages. Use the page arrows or enter a page number and press Enter to jump anywhere in the file. In a viewer, F4 toggles the read-only hexadecimal view. Scroll through the entire file or choose Go to offset to jump to a decimal or hexadecimal byte address. A Markdown preview renders Mermaid diagrams and supports links between documents. Ctrl-click a Markdown link (or Command-click on macOS) to open another viewer tab. When you open Markdown, wide Mermaid diagrams fit the reading width by default, even with a larger saved text size. Smaller diagrams keep their original size. Set a persistent Default diagram scale (%) in Options → Viewer → Mermaid diagrams. Drag a wide diagram left or right with the mouse, or use its horizontal scroll control. The control stays visible as you scroll through the diagram. Tall diagrams scroll vertically with the document. Ctrl-wheel zooms the text and all diagrams together. Move the pointer over a diagram’s toolbar or focus a button to emphasize its controls. The zoom and reset buttons adjust just that diagram. Choose Fit horizontally to show both sides of that diagram at once. Choose Open in new window to view a diagram at its current scale in an independent window. You can keep reading and open other diagrams. Zoom or drag inside each window, or use Fit to show the whole diagram. Change or disable Font zoom with mouse wheel in Options → Keyboard shortcuts. In Options → Viewer → Reading area, set the shared maximum width and the background beside a narrower column. Under Viewer → Markdown, rendered Markdown can use the shared width, a custom width, or full width. Source mode uses the shared width. In Text Viewer, find the file path on the right side of the menu row, before the status indicators. Hover over it for the full path and choose Copy file path to copy it. Closing a text file returns to the file pane or document that opened it. If that document has closed, focus returns to the file panes.\n\nIn text and source views, including Markdown Source and paged files, choose Display → Show whitespace to reveal spaces and tabs. Set the shared Tab width in Options → Viewer or Options → Editor. The default is four columns, and the width applies even with markers hidden. Both settings are remembered and leave copied or saved text intact.\n\nIn Text Viewer, the File menu offers Open in Editor for editable files and Close. Navigate offers Search in rendered Markdown and Hex in source and hexadecimal views. The menus show the configured shortcuts. Use the search bar to find text within the current document and the match arrows to move through hits. The counter shows the current match and total. Markdown Back and Forward follow visited links. Preview and Source switch rendered Markdown and text. Formatted HTML adjusts the source display. The diagnostic log uses Entries for expanded records and Source for the original lines.\n\nFor supported images, Previous and Next follow the source pane’s order and are disabled at the ends. Fit shows the whole image, 100% uses actual pixels, and the percentage shows current zoom. Drag a zoomed image to pan. Hex shows bytes. Open in Editor is available when the file is editable. The close button returns to the file pane or previous document. Use Document header in Options → Appearance → Window to change the header color.\n\nOpen Show blame in [[gitView|Git View]] to read attribution for a committed text file. The header identifies the revision and path. Select the author beside a line to see its commit and use Back to line to return. Wrap lines keeps attribution aligned with the text.",
    editor: "Use F4 on a text file to edit it or Shift+F4 to create and edit a file. With the editable text focused, Tab inserts a tab character and Shift+Tab removes one leading indentation level from each selected line or the current line. Reassign or remove these shortcuts in Options → Keyboard shortcuts. Use Ctrl+M (Alt+Shift+M on macOS) to toggle Tab focus navigation while editing. Text files over 8 MiB open in pages. You can edit multiple pages before saving, and Save applies all edits. If the file changed outside Dirlume, reopen it before saving. Choose the syntax language if the automatic choice does not suit the file. Save before closing or use Esc, which prompts if there are unsaved changes. Switch between editors, [[viewer|viewers]], and [[files|file panels]] using the open documents bar. Options → Editor sets the editor's font and size. In Text Editor, the file path is on the right side of the menu row. Hover over it to see the full path. Choose Copy file path to copy it. Switching between Viewer and Editor keeps the original return destination. Closing the file returns to the pane or document that opened it.\n\nIn text and source views, including Markdown Source and paged files, choose Display → Show whitespace to reveal spaces and tabs. Set the shared Tab width in Options → Viewer or Options → Editor. The default is four columns, and the width applies even with markers hidden. Both settings are remembered and leave copied or saved text intact.\n\nFor local PNG and JPEG images, rotate left or right, or choose Crop. Adjust the crop rectangle and ratio, then apply it. Undo and Redo step through edits. Zoom and Fit change the display. Save a copy writes a separate file. Replace original asks for confirmation. Close prompts to keep editing or discard unsaved changes. When a text file changed on disk while you worked, choose whether to keep editing or reload it from disk. Use Document header in Options → Appearance → Window to change the header color.",
    terminal: "From a local file pane, press F2 or choose Commands → User Menu. Change Open User Menu and Rename separately under Options → Keyboard shortcuts. Use Files → Rename to rename the selected item. The menu captures the working folder, focused item, and marked paths on opening. Use Menu source to switch between the current folder, a parent folder, and the personal menu. Choose New command or Edit, fill in Name and Shell commands, and choose Save command to return to the same menu. Use Insert value for pane paths, focused and marked values, or run-time inputs. Put values where shell arguments go without adding extra quotes. Hotkeys, visibility, name masks, and run-time inputs are under Advanced options. Use Show hidden entries to find filtered commands and Manage menus to organize submenus, separators, and commands. Use Up and Down to select, Right to open a submenu, and Left or Escape to go back. Choose Run, press Enter, or use the entry’s hotkey when you are ready. Folder menus use .dirlume-menu.json. Review the current definition before approving it for the session. A changed definition needs fresh approval. Commands use a separate local shell session and stop on a failed step or when you press Stop. Read the output and exit status in Terminal. Completed steps can leave changes.\n\nClick Terminal beside the command line to open the interactive shell. With the .. row focused in a local or SSH pane, Insert selected path in command line inserts the current folder. Enter on the row opens its parent. In supported shells, the terminal and the active local or [[remote|SSH pane]] synchronize directories at the prompt. While you edit a single-line command, use Up or Down to select a suggestion, Tab to insert it, and Esc to dismiss the list. Enter inserts the selected suggestion or runs the draft if nothing is selected. On Windows, type a KSwitcher snippet prefix such as `;` at a supported shell prompt. Tab inserts the selected single-line KSwitcher snippet into the draft. The command stays editable until you press Enter. Snippets with key actions or pauses are excluded. With a Linux SSH pane active, the command line suggests commands and paths from that host even before you open Terminal. At the SSH prompt, suggestions follow the shell’s environment. When you return to an open SSH terminal from another pane, edits still use that SSH session’s folder and environment. After a space, the Linux SSH terminal can suggest options from Bash alongside other matches. Type - or -- to filter option names. After a standalone --, option discovery stops. Selecting a directory suggestion appends a slash and offers children of that directory. On Windows and Linux, suggestions follow the installed completion rules for the command. Type an explicit path such as ./ to request file and folder suggestions where path completion is allowed. On Windows and Linux, including Linux SSH sessions, both inputs suggest Docker subcommands and options. Type a space after a command such as docker ps or docker image ls to see its options. If an option expects a value, use the values suggested by Docker or continue typing. Container names and IDs follow the Docker context. Compose service names follow the project selected by the working directory, -f, or COMPOSE_FILE. PowerShell, Bash, and Zsh submissions appear in the shared dated history. Press Alt+F8 to search it. Commands use a monospaced font with shell syntax colors when the shell is known. Selecting a row restores the complete command, including its line breaks and indentation, to the Command line for editing. [[files|Click a file pane]] to restore file shortcuts.\n\nRight-click, or Control-click on macOS, to open Copy, Paste, and Select All. Select All includes retained scrollback.\n\nCopy selected text with Ctrl+Shift+C on Windows and Ubuntu or Command+C on macOS. Change or disable the shortcut in Options → Keyboard shortcuts. Over an HTTP or HTTPS link, use Open Link or Copy Link Address. Enable Paste on right-click in Options → Terminal to paste directly. Set the terminal font and size there as well.\n\nThe command line can run a single command from the shown directory. Open terminal to keep an interactive session. The title identifies the active shell or connection. The close button ends that session. On Windows, if PowerShell exits or fails to reach its prompt, choose Restart terminal to start a new session in the active local folder. Resubmit any commands that were still queued. Resize using the divider, or hide and restore the file panes with the configured command. Open Command history to review dated commands and reuse a previous entry. If environment variables changed, the notice explains when changes take effect. See [[terminalShortcuts|why file shortcuts are paused]].\n\nOpen File opens in the terminal header to review the time, path, and handoff result of local file opens from either pane. This view includes attempts made while the terminal was hidden. It works when the shell is busy or unavailable and clears when Dirlume restarts.\n\nA new local zsh session opens at the active pane’s folder. The prompt and terminal header show that folder.\n\nRight-click, or Control-click on macOS, to open Copy, Paste, and Select All. Select All includes retained scrollback.\n\nCopy selected text with Ctrl+Shift+C on Windows and Ubuntu or Command+C on macOS. Change or disable the shortcut in Options → Keyboard shortcuts. Over an HTTP or HTTPS link, use Open Link or Copy Link Address. Enable Paste on right-click in Options → Terminal to paste directly. Set the terminal font and size there as well.\n\nThe command line can run a single command from the shown directory. Open terminal to keep an interactive session. The title identifies the active shell or connection. The close button ends that session. On Windows, if PowerShell exits or fails to reach its prompt, choose Restart terminal to start a new session in the active local folder. Resubmit any commands that were still queued. Resize using the divider, or hide and restore the file panes with the configured command. Open Command history to review dated commands and reuse a previous entry. If environment variables changed, the notice explains when changes take effect. See [[terminalShortcuts|why file shortcuts are paused]].\n\nOpen File opens in the terminal header to review the time, path, and handoff result of local file opens from either pane. This view includes attempts made while the terminal was hidden. It works when the shell is busy or unavailable and clears when Dirlume restarts.\n\nIn a local Windows PowerShell terminal or Command line, submit ipconfig /flushdns on its own. If the Windows system executable reports that elevation is required, Windows asks for administrator consent. Approval runs the command in a separate elevated process and reports the outcome. Declining returns to the same terminal. Other commands and scripts run normally.",
    compare: "Choose one text file in [[files|each pane]] or mark two text files in one pane, then open Compare files. Choose Unified or Side-by-side in the toolbar. In Side-by-side, drag the divider to resize the panes and use Show change connectors to trace matching blocks. Turn on whitespace changes when indentation or trailing spaces matter.\n\nPrevious and Next jump between differences. Apply to left and Apply to right use the current change, and are disabled when no applicable change is selected. Collapsed unchanged rows can be expanded. Saving asks which changed versions to write and whether to replace the original or make a copy. Closing with unapplied changes asks whether to keep editing or discard them.",
    googleDrive: "Open Google Drive from either pane’s sources. Add or reconnect an account and approve access in your browser. Press Enter on the connection to open My Drive. Switch between List and Tree as you would for local folders.\n\nUse Shift+F4 for a new text file, F7 for a new folder, Files → Rename to rename, F3 to view, and F4 to edit supported text files. Select a destination in the other pane and use F5 to copy or F6 to move files and folders between My Drive and the computer, or between folders on Drive. Use F8 to move selected items to Google Drive Trash. Delete permanently is available from the file menu. Press F4 on an Office file or a Google Docs, Sheets, or Slides file to open it in the browser for editing. Google Drive applies the permissions of the connected account.\n\nSelect a folder and press F3 to measure its size, including subfolders. Choose Folder sizes to measure all folders shown at the current level. A partial total means some sizes were unavailable.\n\nWhen copying or moving to a local disk, Google Docs, Sheets, Slides, Drawings, and Apps Script files export to DOCX, XLSX, PPTX, PDF, and JSON. Drive saves items without a downloadable export as .url links. During a move, sources represented by links stay in Drive. If a folder contains any links, its Drive source stays intact.",
    remote: "Choose NetBox from either pane’s sources or press 2 in that menu. NetBox lists saved FTP, FTPS, and SFTP connections with their name, protocol, and host. Press Shift+F4 to add a profile, F4 to edit, or Enter to connect. On the Session page choose a protocol and test the connection before saving. For FTP, choose No encryption, Explicit TLS, or Implicit TLS. Existing plain FTP profiles still use port 21 by default. The suggested port for implicit TLS is 990. Explicit TLS upgrades the control connection before authentication, and implicit TLS starts with TLS. Both modes encrypt file transfers and directory listings, validate the server certificate against trusted roots and the profile host, and report TLS errors without falling back to plain FTP. New profiles start with SFTP (SSH). Select a visible page name or use the arrow buttons at the right of the page strip. Ctrl+PageUp and Ctrl+PageDown move between available pages by default. Use Options → Keyboard shortcuts to change or disable these keys. NetBox keeps draft values when switching pages. On Directories, set an absolute starting folder or leave it blank for the server default. If enabled, Remember last used directory tries the last successfully opened folder first. Explicit bookmarks use their saved paths. Back and Forward can reuse visited listings. Cache directory changes also reuses previous results for ordinary navigation. Refresh always reads the server again. SFTP can resolve symbolic links to directories. On Environment, set the fallback line ending for files without line breaks. Existing line endings and binary transfer bytes are preserved. FTP also offers legacy filename encoding and timezone options for LIST timestamps. Use a fixed offset from UTC or local time with the file’s historical offset or the current local offset. UTC timestamps are used as received. Preserve modification times on downloads sets the local copy’s modification time. Plain FTP sends passwords and files without encryption. A saved FTP profile can reconnect to the last folder at startup. On FTP and SFTP, use List or Tree to browse. F7 creates a folder and Shift+F4 creates and opens a text file in the selected Tree folder or the displayed folder in List. If SFTP denies a file operation, Dirlume offers to continue with sudo on the affected connection. This applies to creation, renaming, transfers, deletion, viewing images and hexadecimal data, Quick View, and measuring folders. During a transfer or deletion this retries the operation that was denied and preserves the work already completed. Use F5 to copy or F6 to move files and folders between local folders, FTP, FTPS, SFTP, Dirlume shares, KSwitcher LAN folders, and archives that allow the requested operation. Dirlume keeps each source until its destination copy is committed.\n\nUnder Environment → Remote recycle bin, choose an existing absolute server folder and enable moving deleted items there. F8 or Delete moves items using a server-side rename. Inside the recycle bin, each item is stored under its own folder followed by its original path. Move the item back on the server to recover it. Shift+Delete still asks before permanent deletion. If the bin is inaccessible or the server refuses the move, Dirlume reports the error. For SFTP, you can also preserve previous versions when overwriting files.\n\nOn FTP(S), set MLSD to Auto to fall back to LIST when the server rejects MLSD, On to require MLSD, or Off to use LIST. Passive lets this computer open the data connection. Active requires the server to reach a listener on this computer. An empty username uses anonymous login. Send an empty password leaves the saved password available for later. Post-login commands run in order after authentication. The two 0xFF options independently change command escaping and PWD decoding for legacy servers.\n\nOn the Connection page, set the response timeout to Default, Disabled, or a custom interval from 1 to 3600 seconds. The default is 12 seconds for FTP and 15 seconds for SFTP. FTP custom keepalive uses TCP probes, and SFTP uses SSH keepalive messages. The default SSH interval is 30 seconds. Auto uses the available addresses, while IPv4 and IPv6 restrict direct connections to a family. On an SSH jump route the address family applies to the first hop. Enable larger data buffers for FTP if useful. Use Cancel test or Escape to stop a stalled connection test.\n\nOn SFTP, leave the server command blank to use the standard subsystem. Enter a command if the server starts SFTP differently. Enable signed modification times only for servers that use signed 32-bit seconds for dates before 1970. The client uses SFTP version 3. On Shell, choose the default shell, Bash, Zsh, or sh for the SSH terminal.\n\nOn the Proxy page, select SOCKS5 or HTTP CONNECT and enter the proxy host and optional credentials. The system credential store holds the proxy password. Choose where destination names resolve and whether localhost and loopback addresses connect directly. FTP and FTPS use passive data mode with a proxy. For SSH and SFTP the proxy connects to the first jump host when configured. SSH forwards the rest of the route. A failed proxy is reported on the configured route.\n\nFor SSH and SFTP, enter the destination and its credentials. Under Jump hosts, choose Add jump host for each server. Enter a password or private key and optional passphrase for each hop. The Route preview shows the order. Each intermediate server must allow TCP forwarding to the next. Test connection lists the destination’s initial folder. Verify the SHA-256 fingerprint of each unfamiliar server with its administrator. Test approvals apply only to the test. Choose Trust and connect during first use of the saved profile. A changed key blocks the connection. The saved route also applies to transfers, folder shortcuts, and the [[terminal|SSH terminal]]. If the terminal closes unexpectedly, Dirlume checks whether SFTP still works. If SFTP cannot recover, the pane returns to its NetBox connections. Opening or refreshing a folder can also confirm connection loss. Select the saved connection to reconnect. A normal shell exit leaves the file pane open.\n\nChoose SMB from either pane’s sources on Windows, macOS, or Ubuntu. Add a connection by server name, IP address, or share address such as smb://server/documents. Windows also supports UNC paths. Open a server to see its shares. At a share’s root, go to the parent folder to return to the server. Enter credentials if prompted. Remember credentials saves the sign-in in the system credential store. Ubuntu uses the GVfs SMB and FUSE packages.\n\nWhile browsing a remote folder, select the source breadcrumb to reopen the saved connections list. Choose a dimmed breadcrumb to return directly to the connection or a folder. Back returns to the same folder. Use Remote machine for a saved Dirlume server connection. For a KSwitcher connection on Windows, add Dirlume.exe to Trusted clients in KSwitcher’s Computers window. Open the paired drive under KSwitcher LAN. With KSwitcher 0.8.0 or newer on both PCs, grant Allow write to copy, create, rename, or save edits and Allow delete to use the remote Recycle Bin or permanent deletion. Move needs both grants. Copy and Move between paths on the same paired PC run there. When the broker supports individual conflict prompts, choose Ask. Other versions offer Stop on conflict, Skip, and Overwrite all. If the connection goes away, check that KSwitcher is running on both computers. The pane resumes browsing when the connection returns, and you can use Refresh folder to retry immediately. Dirlume Server shares provide read access by default. Select a file or folder and press F5 to copy it to a local destination. If the host started the server with --allow-write, you can also create, edit, rename, move, and delete items in List or Tree, and copy items to the shared folder. The host’s filesystem permissions still apply. When a local folder with the same name exists, choose how to handle conflicting items. In Options → Computers, create a Dirlume LAN group on one computer. Copy its group code and use Join group with the same code on every other computer. Open a drive under Dirlume LAN in either pane’s sources. Dirlume gets computer names automatically. Press F5 to copy files and folders into or out of Dirlume LAN. Press F6 to move files and folders. Dirlume keeps the source until the destination copy is committed. In List or Tree, use F7 to create folders, Shift+F4 to create text files, F4 to edit supported text files, Files → Rename to rename and Delete to request permanent deletion. The host enables these actions with Allow group members to change files and folders. After restarting, Dirlume rejoins the saved group when the local network is available. It starts with read-only access. Choose Leave group to stop sharing and forget the group. Legacy pairing codes are available for older Dirlume versions.",
    processes: "Open a pane's sources and choose Processes or press 0. Click a heading to sort. Hold Alt and type a letter to open [[search|Quick search]] by process name. Select one or more rows, then press F8 to review the confirmation before ending the selected processes.",
    general: "Choose the interface language or the [[remote|provider used by Connect]]. On Windows, choosing KSwitcher also lets you specify the installation folder. Version shows the installed build. Search settings finds pages and individual controls. Use [[appearance|Pick an element]] to see the appearance controls for something on screen. Esc returns to the same page. Picker history keeps successful picks by date. Apply saves changes while keeping Options open, and Done saves and closes it.\n\nImport settings lets you pick settings groups and color schemes from an archive. Export settings writes the selected groups and schemes. Apply is unavailable until there is a valid change, and Done is disabled while input is invalid. Where Cancel is shown it closes the dialog without applying its draft. See [[shortcuts|shortcut schemes]] and [[appearance|appearance settings]].\n\nOn Windows, normal launches and administrator launches of the same copy use dirlume-settings.json beside Dirlume.exe. On upgrade, open Dirlume normally once to copy older preferences into a writable app folder. In a protected folder, use Open as administrator from an ordinary Dirlume window to initialize a missing settings file. If saving is denied, Options displays an error and keeps the last saved preferences.",
    profiles: "Profiles save a color scheme, panel layout, both pane modes, right-click selection, and the effective keyboard shortcuts. Choose Dirlume, Far Manager, Total Commander, or a custom profile. Review the changes, then choose Apply or Done. Closing Options discards pending changes.\n\nSave current setup as profile captures your settings. Duplicate profile copies a saved definition. A profile shows Modified when you change its settings. Update a custom profile to keep those changes, or reapply the profile to restore it. When switching from a modified setup, you can save it, discard the changes, or cancel. Deleting a custom profile keeps the current setup. If its saved color scheme is missing, the profile shows the built-in scheme it will use. Edit profile bindings in [[shortcuts|Keyboard shortcuts]] under Current setup shortcuts.",
    appearance: "Open Appearance → [[window|Window]] to choose the active color scheme, create a custom scheme, or set favorites for System mode. Preview shows your draft colors and fonts while you edit. Use Apply to see the changes in the main window.",
    window: "Set the main window background, toolbar, text, borders, and focus color. Click a swatch to pick a color, or enter its HEX value. Use the reset button beside a color to restore that setting to the base theme. Clear Show status bar to give the workspace more room. The resize grip stays at the bottom-right. Action confirmations appear briefly, and errors stay until you dismiss them.",
    panels: "Set colors for [[files|file panel surfaces]], names, metadata, folder icons, and active or inactive selections. The sample panel in Preview lets you read the colors together. Turn on Hide action button icons in Options → Main File Panels to show text in the File actions bar in every layout.",
    fileTypes: "Edit the default filename extension groups or create a group with its own color and font family. Type a suffix and choose Add extension to assign it to the group. If the suffix already belongs to another group, Options shows its name. Choose Move extension and confirm the move, then select Apply or Done. Matching uses the last extension and ignores letter case. Hidden and system entries use their attribute colors. Set visibility in [[files|Main File Panels]].",
    dialogs: "Set dialog backgrounds, headers, text, error colors, and buttons. Use the preview to check text and controls against their backgrounds.",
    textTools: "Customize the font, background, text, selection, and change colors for [[compare|Compare files]]. Shared text and syntax colors still serve as defaults for the [[editor|Editor]], [[viewer|Viewer]], and [[terminal|Terminal]]. Open the feature pages for Hex Viewer, Markdown preview, or Command line. Use each field’s reset button to resume inheritance.",
    fonts: "Choose font families and sizes for the main window, file panels, file pane dialogs, the Options window, and shared text tools. You can also change both dialog font groups on [[dialogs|Appearance → Dialogs]]. Type in a family field to filter installed fonts, or open the dropdown and choose one. Feature pages can override shared fonts for the [[viewer|Viewer]], [[editor|Editor]], and [[terminal|Terminal]].",
    viewFonts: "Hover over the main window, either file pane, Folder shortcuts or another file pane dialog, Options, [[terminal|Terminal]], the command line, [[compare|Compare files]], or a document view and use Ctrl+Wheel to resize its text. Related dialogs share the adjustment. Reassign or disable Font zoom with mouse wheel in Keyboard shortcuts. Changes made with the mouse-wheel shortcut appear here and persist across restarts. Clear an override to inherit the corresponding font size.",
    shortcuts: "In dialogs, use the arrow keys to move between available action buttons in the same group. Press Enter or Space to activate the focused button. Use Tab and Shift+Tab to move between all controls. In the editable text area, these shortcuts insert a tab or outdent lines. See [[editor|Editor]]. Press Alt and the underlined letter in a label or button to focus its control. If controls share a letter, press it again to cycle through them. F9 opens the main menu.\n\nChoose a shortcut scheme in Options. New scheme copies the selected scheme. Use Add shortcut to add a binding, click a binding to replace it, or click its × to remove it. While adding or replacing a binding, the checkbox below the capture field lets you distinguish left and right Ctrl. Restore defaults resets the selected personal scheme. The keys listed in Help are the defaults.\n\nUse Search Help to find a title or phrase anywhere in the offline guide. Open a result to jump to its passage. Clear the search to return to the table of contents.",
  },
  uk: {
    ...controlHelpText.uk,
    terminalShortcuts: "Коли оболонка має фокус, вона отримує натискання клавіш, зокрема комбінацію, яку ви налаштували для копіювання файлів. Оболонка сама обробляє це натискання, тому копіювання файлів не запускається. Натисніть файлову панель, щоб знову користуватися її комбінаціями. Якщо панелі приховані, натисніть «Термінал», щоб повернутися до файлів. Докладніше про команди та історію читайте в [[terminal|довідці термінала]].",
    archives: "Пакети Dirlume містять 7-Zip для роботи з архівами без інтернету. Виберіть локальні файли або папки й натисніть Shift+F1, потім укажіть формат, шлях призначення та параметри стиснення. Натисніть Enter на архіві, щоб відкрити його у [[files|файловій панелі]]. F5 розпаковує вибрані елементи. Щоб скопіювати або перемістити локальні елементи до папки ZIP чи 7z із доступом на запис, натисніть F5 або F6 в іншій панелі й підтвердьте архів і шлях у ньому. Переглядайте архів у режимі списку або дерева. У ZIP або 7z із доступом на запис F7 створює папку, Shift+F4 створює текстовий файл, а Файли → Перейменувати змінює назву вибраного елемента. У дереві нові елементи створюються у вибраній папці або в папці, що містить вибраний файл. В архівах із доступом на запис F6 переміщує елементи до локальної папки або папки архіву з доступом на запис. Елемент вилучається з архіву після завершення копіювання. F4 редагує текстові файли, а F8 видаляє елементи. Зашифровані та багатотомні архіви відкриваються лише для читання. Профілі зберігають параметри архівації без паролів. Щоб відновити файл після архівування, скопіюйте його з кошика до потрібної папки. Системна команда відновлення може вказувати на тимчасову папку, у якій перевірявся файл.",
    files: "Переглядайте папки незалежно у двох панелях. В Ubuntu натисніть Enter на локальному виконуваному файлі .sh, щоб запустити його у вбудованому терміналі з папки скрипта. Клавішу дії Відкрити можна змінити в Параметри → Комбінації клавіш. Для звичайного відкриття файла скористайтеся подвійним кліком або дією Відкрити в системі. Щоб відкрити папку, введіть шлях у полі адреси й натисніть Enter. Для [[operations|вибору кількох елементів]] використовуйте Insert, Shift зі стрілками або Ctrl і клацання. Перетягуйте роздільник, щоб змінити ширину панелей. Режим відображення вибирайте в меню Ліва або Права. Колонки та рядок стану можна змінити в Налаштування → Режими панелей. Ctrl+F12 відкриває меню сортування активної панелі, а F4 у цьому меню змінює додаткові критерії. Клацніть заголовки правою кнопкою, щоб вибрати видимі колонки. У розділі Налаштування → Основні файлові панелі можна змінити видимість прихованих файлів, [[panels|кольори]] й розмір шрифту кожної панелі. Ctrl+Shift+0–9 додає поточну папку до групи закладок, а правий Ctrl+0–9 відкриває цю групу. Керуйте групами через Команди → Закладки папок. У параметрі Вигляд панелей виберіть Стандартний, Подвійні панелі або Класичний коммандер. Подвійні панелі додають кнопки дисків з іконками, вільне місце диска над кожним списком і пласку панель клавіш. Класичний коммандер має щільні рядки, панель дисків над кожною панеллю, відомості про поточний елемент унизу й панель функціональних клавіш.\n\nКоли ви відкриваєте локальний файл у призначеній системою програмі, панель показує стан запиту, а потім підтверджує його передавання або показує помилку. Шлях і результат можна переглянути в розділі [[terminal|Термінал → Відкриття файлів]].\n\nВідкрийте файлове меню для одного файла й виберіть підменю Git. Воно містить доступні для файлу дії «Показати історію», «Показати авторство рядків», «Порівняти з ревізією» та «Показати різницю». Підготовлені й непідготовлені зміни показані окремо. Закриття Git View повертає до файлу. Комбінацію можна змінити в «Налаштування → Клавіатурні скорочення».",
    operations: "Позначте потрібні елементи або залиште курсор на одному з них. Копіювання чи переміщення відкриває діалог із шляхом призначення, зазвичай з [[files|іншої панелі]]. Коли F6 відкриває діалог переміщення із заповненим шляхом, фокус стоїть на кнопці Перемістити. Натисніть Enter, щоб перемістити за цим шляхом, або перейдіть до поля шляху за допомогою Tab чи Shift+Tab і відредагуйте його. Стежте за перебігом операції й вибирайте, як обробити наявні файли чи папки, коли з’явиться запит. Перетягуйте позначені елементи в іншу локальну панель для копіювання або виберіть Перемістити замість копіювання. Системний буфер обміну дає змогу передавати локальні файли між програмами.\n\nПанель дій відкриває переглядач, редактор, копіювання, перейменування чи перенесення, створення файла й папки, кошик, порівняння, позначення та термінал залежно від режиму й джерела. Неактивна кнопка означає, що поточний елемент або представлення не підтримує дію. Коли позначення правою кнопкою вимкнено, короткий правий клік у файловій панелі відкриває меню Dirlume. Для локального елемента у Windows утримуйте праву кнопку пів секунди й відпустіть після появи індикатора, щоб відкрити системне меню. На Ubuntu та для джерел без системного меню утримання відкриває меню Dirlume. Комбінація Відкрити контекстне меню файлів, типово Shift+F10, відкриває меню Dirlume для поточного рядка. Меню позначеного рядка показує групові дії та кількість елементів. Меню непозначеного рядка діє на цей елемент і зберігає попередні позначки. Ті самі клавіші та діалоги доступні в [[search|результатах локального пошуку]] для копіювання, переміщення, кошика й остаточного видалення. Див. [[actionDialogs|діалоги файлових операцій]].\n\nЯкщо під час копіювання чи переміщення папка вже є, Dirlume продовжує в ній і зберігає елементи, які є лише в місці призначення. У режимі «Питати» підтвердження з’являється для конфліктів файлів. «Перезаписати всі» діє для всіх файлів поточної операції, які можна перезаписати. Якщо ввімкнено запит для файлів лише для читання, запам’ятований для них вибір діє лише на ці файли. Запам’ятований вибір для звичайних файлів не скасовує окремого запиту. Якщо в іншій панелі відкрита папка колекції, F5 додає до неї посилання. F5 з колекції копіює вибрані оригінали. Команда «Вилучити з колекції» вилучає посилання або віртуальні папки.\n\nДля одного вибраного елемента введіть нову назву в полі призначення діалогу F6, щоб перейменувати елемент у поточній папці. Інша панель підставляє початковий шлях. Введіть потрібний шлях призначення, щоб перемістити елемент до локальної папки або підключеного джерела. Шлях Google Drive містить підключений акаунт, :/Мій диск і шлях до папки.",
    search: "У файловій панелі утримуйте Alt і введіть літеру, щоб відкрити швидкий пошук. Він шукає в будь-якому місці назв видимих файлів і папок. Назви, що починаються з введеного тексту, показуються першими. Перебирайте збіги стрілками вгору й униз. Клацніть кількість збігів або натисніть Tab і Enter, щоб відкрити таблицю результатів. Вибір рядка переміщує курсор до елемента й повертає фокус у панель. У полі пошуку Enter відкриває поточний збіг, а Esc повертає фокус у панель. Команду «Швидкий пошук за назвою» можна змінити або вимкнути в Налаштування → Клавіатурні скорочення. Для пошуку в підпапках відкрийте Знайти файли й введіть маску, наприклад *.md. Виберіть Показати в панелі, щоб відкрити список збігів у [[files|файловій панелі]], або Перейти до вибраного файла, щоб відкрити його папку.\n\nРядок «Папка та вкладені папки» показує корінь пошуку. У масці файла * відповідає будь-якій кількості символів, а ? — одному символу. Зупинка залишає знайдені збіги. Частковий стан означає, що частина області залишилася неперевіреною. Перехід до файла показує поточний результат, а показ у панелі залишає список у файловій панелі. Закриття завершує пошук.\n\nУ результатах локального пошуку можна копіювати, переміщувати, відправляти до кошика чи остаточно видаляти позначені файли або поточний файл. Успішно переміщені або видалені файли зникають зі списку. Команда «Оновити» повторює пошук із початковою папкою, маскою та параметром прихованих файлів. Панель залишається відкритою навіть за відсутності збігів. Див. [[paneFilter|фільтр поточної папки]].",
    viewer: "Натисніть F3, щоб переглянути файл або виміряти розмір папки. У рядку батьківської папки (..) клавіша F3 і кнопка «Виміряти» підраховують розміри видимих безпосередніх дочірніх папок, зокрема непозначених. У дереві розгорнуті нащадки враховуються в розмірі папки верхнього рівня. Налаштування «Розміри папок» зберігається. Escape зупиняє решту обчислень і зберігає готові результати. Щоб переглянути журнал, виберіть Довідка → Відкрити журнал помилок. У меню Файл цього переглядача виберіть «Очистити журнал помилок» і підтвердьте видалення записів. Текстові файли понад 8 МіБ відкриваються сторінками. Скористайтеся стрілками або введіть номер сторінки й натисніть Enter, щоб перейти до будь-якої частини файла. F4 у переглядачі перемикає шістнадцятковий режим лише для читання. Прокручуйте весь файл або скористайтеся переходом до зміщення, ввівши десяткову чи шістнадцяткову адресу байта. Перегляд Markdown відображає діаграми Mermaid і підтримує посилання між документами. Клацніть посилання на Markdown з Ctrl або Command на macOS, щоб відкрити окрему вкладку. Коли ви відкриваєте Markdown, широкі діаграми Mermaid за замовчуванням вміщуються в ширину області читання навіть зі збереженим збільшеним розміром тексту. Менші діаграми зберігають початковий розмір. Задайте постійний масштаб у розділі Налаштування → Переглядач → Діаграми Mermaid. Перетягуйте широку діаграму мишею вліво або вправо чи скористайтеся повзунком горизонтального прокручування. Він залишається видимим під час перегляду діаграми. Високі діаграми прокручуються вертикально разом із документом. Ctrl із коліщатком масштабує текст і всі діаграми разом. Наведіть вказівник на панель діаграми або переведіть фокус на кнопку, щоб підсвітити елементи керування. Кнопки масштабування й скидання діють лише на цю діаграму. Натисніть «Вмістити по горизонталі», щоб побачити обидва її краї одночасно. Команда «Відкрити в новому вікні» відкриває діаграму в поточному масштабі в незалежному вікні. Можна далі читати документ і відкривати інші діаграми. Масштабуйте й перетягуйте діаграму в кожному вікні або натисніть «Умістити», щоб побачити її повністю. Дію коліщатка можна змінити або вимкнути в налаштуваннях скорочень. У розділі Налаштування → Переглядач можна задати шрифт і окремі розміри для тексту й Markdown. У текстовому переглядачі шлях файла розміщено праворуч у рядку меню, перед індикаторами стану. Наведіть вказівник, щоб побачити повний шлях, і натисніть «Копіювати шлях файла», щоб скопіювати його. Після закриття текстового файла фокус повертається до панелі або документа, з якого його відкрили. Якщо цей документ уже закрито, фокус повертається до файлових панелей.\n\nУ текстових режимах, зокрема у вихідному тексті Markdown і файлах зі сторінками, виберіть Відображення → Показати пробільні символи, щоб побачити пробіли й табуляції. Спільну ширину табуляції задайте в Налаштування → Переглядач або Налаштування → Редактор. Типова ширина становить чотири стовпці й діє навіть із прихованими позначками. Обидва налаштування зберігаються і не змінюють скопійований чи збережений текст.\n\nУ текстовому переглядачі меню «Файл» містить команди «Відкрити в редакторі» для редагованих файлів і «Закрити». У меню «Навігація» доступний «Пошук» в оформленому Markdown і «Hex» у режимах джерела та шістнадцяткового перегляду. У меню показано налаштовані клавіатурні скорочення. Пошук у документі знаходить текст, стрілки переходять між збігами, а лічильник показує номер і кількість. У Markdown кнопки «Назад» і «Уперед» переходять між відкритими посиланнями. Перегляд і джерело перемикають оформлення й текст. Форматування HTML змінює вигляд джерела. Журнал діагностики показує розгортні записи або вихідні рядки.\n\nДля зображень кнопки попереднього й наступного файла дотримуються порядку вихідної панелі та неактивні на краях. «Умістити» показує все зображення, 100% — фактичні пікселі, а відсоток — поточний масштаб. Перетягування зсуває збільшене зображення. Hex показує байти. Редактор доступний для редагованих файлів. Закриття повертає до панелі або попереднього документа. Щоб змінити колір заголовка, відкрийте Налаштування → Вигляд → Вікно й виберіть «Заголовок документа».\n\nУ [[gitView|Git View]] виберіть «Показати авторство рядків», щоб переглянути авторів збереженого в Git файлу. У заголовку вказано ревізію та шлях. Натисніть автора біля рядка, щоб відкрити коміт. «До рядка» повертає до вашої позиції. Перенесення рядків зберігає вирівнювання тексту й авторів.",
    editor: "Натисніть F4 на текстовому файлі, щоб відредагувати його, або Shift+F4, щоб створити файл і почати редагування. Коли фокус у редагованому тексті, Tab вставляє символ табуляції, а Shift+Tab зменшує відступ поточного або вибраних рядків на один рівень. Змініть або вимкніть ці комбінації в Параметри → Комбінації клавіш. Ctrl+M (Alt+Shift+M у macOS) перемикає навігацію фокусом через Tab під час редагування. Текстові файли понад 8 МіБ відкриваються сторінками. Можна змінити кілька сторінок і зберегти всі правки разом. Якщо файл змінився поза Dirlume, відкрийте його знову перед збереженням. За потреби виберіть мову підсвічування вручну. Збережіть файл перед закриттям або натисніть Esc. Якщо є незбережені зміни, з’явиться запит. Для перемикання між редакторами, [[viewer|переглядачами]] та [[files|панелями]] використовуйте смугу відкритих документів. У розділі Налаштування → Редактор задається шрифт редактора. У текстовому редакторі шлях файла розміщено праворуч у рядку меню. Наведіть вказівник, щоб побачити його повністю. Натисніть «Копіювати шлях файла», щоб скопіювати його. Перемикання між переглядачем і редактором зберігає місце повернення. Після закриття файла фокус повертається до панелі або документа, з якого його відкрили.\n\nУ текстових режимах, зокрема у вихідному тексті Markdown і файлах зі сторінками, виберіть Відображення → Показати пробільні символи, щоб побачити пробіли й табуляції. Спільну ширину табуляції задайте в Налаштування → Переглядач або Налаштування → Редактор. Типова ширина становить чотири стовпці й діє навіть із прихованими позначками. Обидва налаштування зберігаються і не змінюють скопійований чи збережений текст.\n\nДля локальних PNG і JPEG можна обертати зображення й обрізати його. Налаштуйте прямокутник і пропорцію обрізання, а тоді застосуйте зміну. Скасування та повтор переходять між змінами. Масштаб і вміщення змінюють перегляд. Збереження копії пише в окремий файл, заміна оригіналу потребує підтвердження. Під час закриття можна продовжити редагування або відкинути незбережені зміни. Якщо текстовий файл змінився на диску, можна залишити чернетку або перечитати файл. Щоб змінити колір заголовка, відкрийте Налаштування → Вигляд → Вікно й виберіть «Заголовок документа».",
    terminal: "У локальній файловій панелі натисніть F2 або відкрийте Команди → Меню користувача. У Параметри → Комбінації клавіш можна окремо налаштувати Відкрити меню користувача й Перейменувати. Щоб перейменувати вибраний елемент, відкрийте Файли → Перейменувати. Меню запам’ятовує робочу папку, поточний елемент і позначені шляхи під час відкриття. У полі Джерело меню можна перемкнутися між меню поточної папки, батьківської папки й особистим меню. Виберіть Нова команда або Редагувати, заповніть Назва й Команди оболонки та натисніть Зберегти команду, щоб повернутися до того ж меню. Вставити значення додає шляхи панелей, значення поточного чи позначених елементів або параметр запуску. Вставляйте значення на місце аргументів без додаткових лапок. Гаряча клавіша, умова видимості, маска імені й параметри запуску розміщені в Додаткові параметри. Увімкніть Показати приховані пункти, щоб знайти відфільтровані команди. У Керувати меню можна впорядковувати команди, підменю й роздільники. Стрілки Вгору й Вниз вибирають пункт, Вправо відкриває підменю, Вліво або Escape повертають назад. Щоб запустити команду, натисніть Виконати, Enter або її гарячу клавішу. Меню папок використовують .dirlume-menu.json. Перед схваленням на поточний сеанс перегляньте вміст. Після зміни файла потрібне нове схвалення. Команди виконуються в окремому локальному сеансі оболонки й зупиняються в разі помилки або після натискання Зупинити. Вивід і код завершення доступні в Терміналі. Виконані кроки можуть залишити зміни.\n\nНатисніть Термінал біля командного рядка, щоб відкрити інтерактивну оболонку. Коли фокус на рядку .. в локальній або SSH-панелі, команда «Вставити вибраний шлях у командний рядок» вставляє шлях поточної папки. Enter на цьому рядку відкриває батьківську папку. У підтримуваних оболонках робоча папка змінюється відповідно до активної локальної або [[remote|SSH-панелі]] після повернення до запрошення. Для однорядкової команди виберіть підказку стрілками, вставте її клавішею Tab або закрийте список клавішею Esc. Enter вставляє вибрану підказку або запускає команду, якщо нічого не вибрано. У Windows введіть префікс сніпета KSwitcher, наприклад `;`, у рядку підтримуваної оболонки. Клавіша Tab вставляє вибраний однорядковий сніпет. Команду можна редагувати до натискання Enter. Сніпети з клавіатурними діями або паузами недоступні. Коли активна SSH-панель Linux, командний рядок пропонує команди й шляхи з віддаленого сервера ще до відкриття термінала. Підказки в SSH-терміналі враховують середовище оболонки. Коли ви повертаєтеся з іншої панелі до відкритого SSH-термінала, підказки й далі враховують папку й середовище цього сеансу. Після пробілу SSH-термінал Linux може показати параметри Bash разом з іншими підказками. Введіть - або --, щоб відфільтрувати параметри за назвою. Після окремого аргументу -- пошук параметрів припиняється. Вибір папки додає скісну риску й показує підказки з її вмісту. У Windows і Linux підказки враховують встановлені правила доповнення команди. Щоб запросити підказки файлів і папок там, де дозволено доповнення шляхів, почніть шлях, наприклад, з ./. У Windows і Linux, зокрема в сеансах SSH до Linux, обидва поля підказують підкоманди й параметри Docker. Введіть пробіл після команди, наприклад docker ps або docker image ls, щоб побачити її параметри. Якщо параметр потребує значення, виберіть підказку від Docker або продовжуйте введення. Назви й ідентифікатори контейнерів залежать від контексту Docker, а назви сервісів Compose від проєкту, вибраного робочою папкою, параметром -f або змінною COMPOSE_FILE. [[files|Клацніть файлову панель]], щоб скористатися її клавішами.\n\nПрава кнопка миші або Control-клік на macOS відкриває меню з діями «Копіювати», «Вставити» та «Вибрати все». «Вибрати все» охоплює збережену історію виводу.\n\nКопіюйте виділений текст комбінацією Ctrl+Shift+C у Windows та Ubuntu або Command+C на macOS. Її можна змінити або вимкнути в Налаштування → Клавіатурні скорочення. Над посиланням HTTP або HTTPS меню також пропонує «Відкрити посилання» та «Копіювати адресу посилання». Щоб вставляти одразу, увімкніть «Вставляти правою кнопкою миші» в розділі Налаштування → Термінал. Там також можна змінити шрифт і розмір.\n\nКомандний рядок запускає окрему команду з показаної папки. Термінал підтримує інтерактивний сеанс. Заголовок показує оболонку або з’єднання. Кнопка закриття завершує сеанс. У Windows, якщо PowerShell завершився або не показав запрошення, натисніть «Перезапустити термінал», щоб почати новий сеанс в активній локальній папці. Надішліть команди, що залишилися в черзі, повторно. Розділювач змінює висоту, а налаштована команда ховає чи повертає панелі. Натисніть Alt+F8, щоб відкрити датовану історію команд і знайти потрібну команду. Команди відображаються моноширинним шрифтом із підсвічуванням синтаксису, якщо оболонка відома. Вибір рядка повертає команду з переносами й відступами в командний рядок для редагування. Повідомлення про середовище пояснює, коли набувають чинності зміни змінних. Див. [[terminalShortcuts|паузу файлових команд]].\n\nВиберіть «Відкриття файлів» у заголовку термінала, щоб переглянути час, шлях і результат передавання запитів із двох панелей. Тут також є спроби, зроблені, коли термінал був прихований. Розділ працює, навіть коли оболонка зайнята або недоступна. Після перезапуску Dirlume список очищується.\n\nНовий локальний сеанс zsh відкривається в папці активної панелі. Цю папку показано в запрошенні оболонки й заголовку термінала.\n\nПрава кнопка миші або Control-клік на macOS відкриває меню з діями «Копіювати», «Вставити» та «Вибрати все». «Вибрати все» охоплює збережену історію виводу.\n\nКопіюйте виділений текст комбінацією Ctrl+Shift+C у Windows та Ubuntu або Command+C на macOS. Її можна змінити або вимкнути в Налаштування → Клавіатурні скорочення. Над посиланням HTTP або HTTPS меню також пропонує «Відкрити посилання» та «Копіювати адресу посилання». Щоб вставляти одразу, увімкніть «Вставляти правою кнопкою миші» в розділі Налаштування → Термінал. Там також можна змінити шрифт і розмір.\n\nКомандний рядок запускає окрему команду з показаної папки. Термінал підтримує інтерактивний сеанс. Заголовок показує оболонку або з’єднання. Кнопка закриття завершує сеанс. У Windows, якщо PowerShell завершився або не показав запрошення, натисніть «Перезапустити термінал», щоб почати новий сеанс в активній локальній папці. Надішліть команди, що залишилися в черзі, повторно. Розділювач змінює висоту, а налаштована команда ховає чи повертає панелі. У датованій історії команд можна вибрати й повторно використати попередню команду. Повідомлення про середовище пояснює, коли набувають чинності зміни змінних. Див. [[terminalShortcuts|паузу файлових команд]].\n\nВиберіть «Відкриття файлів» у заголовку термінала, щоб переглянути час, шлях і результат передавання запитів із двох панелей. Тут також є спроби, зроблені, коли термінал був прихований. Розділ працює, навіть коли оболонка зайнята або недоступна. Після перезапуску Dirlume список очищується.\n\nУ локальному терміналі PowerShell або в командному рядку Windows введіть ipconfig /flushdns як окрему команду. Якщо системна програма Windows повідомить, що потрібні права адміністратора, Windows попросить підтвердження. Після згоди команда виконується в окремому процесі з підвищеними правами, а результат з’являється в терміналі. Після відмови можна продовжувати роботу в тому самому терміналі. Інші команди й сценарії виконуються як зазвичай.",
    compare: "Виберіть по текстовому файлу в [[files|кожній панелі]] або позначте два файли в одній панелі й відкрийте Порівняти файли. На панелі інструментів виберіть Об’єднаний або Поруч. У вигляді Поруч можна перетягнути роздільник і показати зв’язки між змінами. Увімкніть показ пробільних змін, якщо важливі відступи або пробіли в кінці рядків.\n\n«Попередня» і «Наступна» переходять між відмінностями. Застосування ліворуч або праворуч переносить поточну зміну й недоступне, якщо немає придатного виділення. Згорнуті незмінені рядки можна розкрити. Збереження запитує, який бік записати та чи замінити оригінал або створити копію. Під час закриття з незбереженими змінами можна продовжити редагування або відкинути їх.",
    googleDrive: "Відкрийте Google Drive у джерелах будь-якої панелі. Додайте або підключіть акаунт повторно й надайте доступ у браузері. Натисніть Enter на підключенні, щоб відкрити Мій диск. Перемикайтеся між списком і деревом так само, як у локальних папках.\n\nНатисніть Shift+F4 для нового текстового файла, F7 для нової папки, Файли → Перейменувати для зміни назви, F3 для перегляду та F4 для редагування підтримуваних текстових файлів. Виберіть місце призначення в іншій панелі й натисніть F5 для копіювання або F6 для переміщення файлів і папок між Моїм диском і комп’ютером або між папками на Диску. Натисніть F8, щоб перемістити вибрані елементи до кошика Google Drive. Остаточне видалення доступне в меню файлів. Натисніть F4 на файлі Office або документі, таблиці чи презентації Google, щоб відкрити його для редагування в браузері. Google Drive застосовує права підключеного акаунта.\n\nВиберіть папку й натисніть F3, щоб обчислити її розмір разом із вкладеними папками. Виберіть «Розміри папок», щоб обчислити розміри всіх папок поточного рівня. Частковий підсумок означає, що деякі розміри недоступні.\n\nПід час копіювання або переміщення на локальний диск Google Docs, Sheets, Slides, Drawings і Apps Script експортуються у DOCX, XLSX, PPTX, PDF і JSON. Елементи без доступного експорту зберігаються як посилання .url. Під час переміщення джерела цих посилань залишаються в Drive. Якщо папка містить такі посилання, її джерело в Drive зберігається цілком.",
    remote: "Виберіть NetBox у джерелах будь-якої панелі або натисніть 2 у цьому меню. NetBox показує збережені підключення FTP, FTPS і SFTP з назвою, протоколом і хостом. Натисніть Shift+F4, щоб додати профіль, F4 — щоб редагувати, або Enter — щоб підключитися. На сторінці «Сеанс» виберіть протокол і перевірте підключення перед збереженням. Для FTP виберіть підключення без шифрування, явний або неявний TLS. Типовий порт звичайного FTP і явного TLS — 21, неявного TLS — 990. Явний TLS вмикається до автентифікації, неявний — на початку підключення. Обидва режими шифрують передавання файлів та списки папок і перевіряють довіру до сертифіката та його відповідність хосту. Якщо перевірку не пройдено, підключення завершується помилкою. Типовий протокол нового профілю — SFTP (SSH). Виберіть назву сторінки або скористайтеся стрілками праворуч. Типові Ctrl+PageUp і Ctrl+PageDown переходять між доступними сторінками. Змінити або вимкнути скорочення можна в розділі «Налаштування» → «Клавіатурні скорочення». NetBox зберігає чернетку під час перемикання сторінок. На сторінці «Каталоги» задайте абсолютний шлях до початкової папки або залиште поле порожнім для типової папки сервера. Якщо ввімкнено запам’ятовування, NetBox спочатку пробує останню успішно відкриту папку. Закладки відкривають збережений шлях. «Назад» і «Вперед» можуть використати кеш відвіданих папок. Кеш переходів діє й під час звичайної навігації. Оновлення завжди перечитує сервер. Для SFTP можна визначати цілі символічних посилань на папки. На сторінці «Середовище» виберіть закінчення рядків для файлів без переносів. Наявні закінчення та байти двійкових файлів зберігаються. Для FTP можна вибрати застаріле кодування імен і часовий пояс для позначок LIST. Використовуйте фіксоване зміщення від UTC або місцевий час зі зміщенням на дату файла чи поточним зміщенням. Позначки UTC використовуються без змін. Збереження часу зміни під час завантаження задає цей час для локальної копії. Звичайний FTP передає паролі й файли без шифрування. Збережений профіль FTP може відкрити останню папку під час запуску. У FTP і SFTP можна переглядати папки в списку або дереві. F7 створює папку, а Shift+F4 створює й відкриває текстовий файл у вибраній папці дерева або відкритій папці списку. Якщо SFTP відмовить у файловій операції, Dirlume запропонує продовжити з sudo для цього підключення. Це стосується створення, перейменування, передавання, видалення, перегляду зображень і шістнадцяткових даних, швидкого перегляду та вимірювання папок. Під час передавання або видалення повторюється дія, у якій було відмовлено, а завершені дії зберігаються. Натисніть F5 або F6, щоб копіювати або переміщувати файли й папки між локальними папками, FTP, FTPS, SFTP, спільними папками Dirlume, папками KSwitcher LAN та архівами, які дозволяють потрібну дію. Dirlume зберігає оригінал до завершення запису копії.\n\nУ розділі Середовище → Віддалений кошик виберіть наявну папку за абсолютним шляхом на сервері та ввімкніть переміщення видалених елементів. F8 або Delete переміщує елементи перейменуванням на сервері. У кошику кожен елемент зберігається в окремій папці зі своїм початковим шляхом. Щоб відновити елемент, перемістіть його назад на сервері. Shift+Delete запитує підтвердження остаточного видалення. Якщо кошик недоступний або сервер відмовляє в переміщенні, Dirlume повідомляє про помилку. Для SFTP можна також зберігати попередні версії перезаписаних файлів.\n\nНа сторінці «FTP(S)» автоматичний режим MLSD переходить на LIST, якщо сервер відхиляє MLSD. «Увімкнено» вимагає MLSD, а «Вимкнено» використовує LIST. У пасивному режимі з’єднання для даних відкриває цей комп’ютер. В активному режимі сервер має підключитися до порту цього комп’ютера. Порожнє ім’я користувача означає анонімний вхід. Надсилання порожнього пароля залишає збережений пароль для подальшого використання. Команди після входу виконуються послідовно після автентифікації. Два параметри 0xFF окремо керують обробкою байта в командах і відповідях PWD для застарілих серверів.\n\nНа сторінці «Підключення» можна залишити тайм-аут відповіді за замовчуванням, вимкнути його або встановити від 1 до 3600 секунд. За замовчуванням це 12 секунд для FTP і 15 секунд для SFTP. Для підтримання з’єднання FTP використовує перевірки TCP, а SFTP — повідомлення SSH. Типовий інтервал SSH — 30 секунд. Автоматичний режим використовує доступні адреси, а IPv4 та IPv6 обмежують пряме підключення відповідною версією IP. У маршруті SSH через проміжні вузли це налаштування стосується першого вузла. Для FTP можна ввімкнути більші буфери даних. Щоб зупинити перевірку, натисніть «Скасувати перевірку» або Escape.\n\nНа сторінці «SFTP» залиште команду сервера порожньою для типової підсистеми. Задайте команду, якщо сервер запускає SFTP іншим способом. Увімкніть знаковий час зміни для серверів, що кодують дати до 1970 року знаковими 32-бітними секундами. Клієнт використовує SFTP версії 3. На сторінці «Shell» виберіть типову оболонку, Bash, Zsh або sh для термінала SSH.\n\nНа сторінці «Проксі» виберіть SOCKS5 або HTTP CONNECT, введіть сервер проксі й за потреби облікові дані. Пароль проксі зберігається в системному сховищі облікових даних. Виберіть, де розпізнавати імена серверів і чи підключатися до localhost та адрес loopback напряму. FTP і FTPS через проксі використовують пасивний режим. Для SSH і SFTP проксі підключається до першого проміжного сервера, якщо його задано. Решту переходів виконує SSH. Якщо проксі недоступний, Dirlume повідомляє про помилку налаштованого маршруту.\n\nДля SSH і SFTP вкажіть кінцевий сервер і дані для входу. У розділі «Проміжні SSH-сервери» натисніть «Додати проміжний сервер» для кожного переходу. Для кожного сервера вкажіть пароль або приватний ключ і, за потреби, його парольну фразу. «Маршрут» показує порядок серверів. Кожен проміжний сервер має дозволяти перенаправлення TCP до наступного. Кнопка «Перевірити підключення» отримує список файлів початкової папки кінцевого сервера. Звірте відбиток SHA-256 кожного нового сервера з його адміністратором. Підтвердження під час перевірки діє лише для цієї перевірки. Під час першого відкриття збереженого підключення натисніть «Довіряти й підключитися». Якщо ключ змінився, підключення блокується. Збережений маршрут діє також для передачі файлів, закладок папок і [[terminal|SSH-термінала]]. Якщо термінал завершується несподівано, Dirlume перевіряє доступ через SFTP. Якщо доступ втрачено, панель повертається до списку NetBox. Під час відкриття чи оновлення папки діє така сама перевірка. Виберіть збережене підключення для повторного входу. Звичайний вихід з оболонки залишає файлову панель відкритою.\n\nВиберіть SMB у джерелах будь-якої панелі у Windows, macOS або Ubuntu. Додайте підключення за іменем сервера, IP-адресою або адресою спільної папки, наприклад smb://server/documents. У Windows також доступні шляхи UNC. Відкрийте сервер, щоб побачити його спільні папки. З кореня спільної папки перейдіть до батьківської папки, щоб повернутися до сервера. Якщо з’явиться запит, введіть дані для входу. Параметр «Запам’ятати облікові дані» зберігає їх у системному сховищі. В Ubuntu потрібні пакунки GVfs для SMB і FUSE.\n\nУ віддаленій папці натисніть назву джерела в адресному рядку, щоб відкрити список збережених підключень. Виберіть приглушений сегмент, щоб повернутися до підключення або папки. «Назад» повертає до тієї самої папки. Для збереженого підключення до сервера Dirlume виберіть «Віддалений комп’ютер». У Windows додайте Dirlume.exe до списку Trusted clients у вікні комп’ютерів KSwitcher. Щоб переглянути файли ПК, спареного через KSwitcher, відкрийте його диск у розділі KSwitcher LAN. У KSwitcher 0.8.0 або новішому на обох ПК надайте дозвіл Allow write для копіювання, створення, перейменування та збереження змін, а Allow delete — для віддаленого кошика й видалення назавжди. Для переміщення потрібні обидва дозволи. Копіювання й переміщення між шляхами на одному спареному ПК виконуються на ньому. Якщо KSwitcher підтримує запити для окремих конфліктів, виберіть «Запитувати». В інших версіях можна зупинятися при конфлікті, пропускати елементи або перезаписувати всі. Якщо з’єднання зникло, перевірте, чи запущено KSwitcher на обох комп’ютерах. Панель відновить перегляд після відновлення з’єднання. Для негайної спроби скористайтеся кнопкою оновлення папки. Спільні папки сервера Dirlume за замовчуванням доступні для читання. Виберіть файл або папку й натисніть F5, щоб скопіювати їх у локальну папку. Якщо власник запустив сервер із параметром --allow-write, можна також створювати, редагувати, перейменовувати, переміщувати й видаляти елементи у списку або дереві та копіювати їх до спільної папки. Діють права файлової системи сервера. Якщо в цілі вже є однойменна папка, виберіть дію для елементів, що конфліктують. У Налаштування → Комп’ютери створіть групу Dirlume LAN на одному комп’ютері. Скопіюйте код і приєднайтеся з тим самим кодом на решті комп’ютерів. Відкрийте диск у розділі Dirlume LAN меню джерел будь-якої панелі. Dirlume автоматично визначає назви комп’ютерів. Натисніть F5, щоб копіювати файли й папки в Dirlume LAN або з нього. Натисніть F6, щоб перемістити файли й папки. Dirlume зберігає джерело до завершення запису копії в місці призначення. У списку або дереві натисніть F7 для створення папки, Shift+F4 для створення текстового файла, F4 для редагування, Файли → Перейменувати для зміни назви або Delete для остаточного видалення. Власник комп’ютера має дозволити учасникам групи змінювати файли й папки. Після перезапуску Dirlume знову приєднується до збереженої групи, коли локальна мережа доступна. Спочатку дозволено лише читання. Команда «Вийти з групи» припиняє доступ і видаляє збережену групу. Старі коди спарювання доступні для попередніх версій Dirlume.",
    processes: "Відкрийте джерела панелі та виберіть Процеси або натисніть 0. Клацніть заголовок колонки для сортування. Утримуйте Alt і введіть літеру, щоб відкрити [[search|швидкий пошук]] за назвою процесу. Виберіть один або кілька рядків і натисніть F8, щоб відкрити підтвердження завершення процесів.",
    general: "Виберіть мову інтерфейсу й [[remote|постачальника для кнопки Підключити]]. У Windows під час вибору KSwitcher можна вказати папку встановлення. Версія показує номер встановленої збірки. Поле Пошук налаштувань знаходить розділи й окремі параметри. Кнопка [[appearance|Вибрати елемент]] відкриває налаштування оформлення вибраного елемента. Esc повертає на ту саму сторінку. Історія вибору зберігає вибрані елементи за датою. Застосувати зберігає зміни та залишає вікно відкритим, а Готово зберігає й закриває його.\n\nІмпорт налаштувань дозволяє вибрати групи й колірні схеми з архіву. Експорт записує вибрані групи та схеми. «Застосувати» доступно після дійсної зміни, «Готово» недоступно, якщо введені дані помилкові. Якщо є кнопка скасування, вона закриває діалог без застосування чернетки. Див. [[shortcuts|схеми клавіш]] і [[appearance|оформлення]].\n\nУ Windows звичайний запуск і запуск від імені адміністратора тієї самої копії використовують dirlume-settings.json поруч із Dirlume.exe. Після оновлення один раз відкрийте Dirlume звичайним способом, щоб перенести старі параметри до папки програми, якщо вона доступна для запису. Якщо папка захищена від запису, скористайтеся командою «Відкрити від імені адміністратора» у звичайному вікні Dirlume, щоб створити файл налаштувань. Якщо зберегти зміни не вдалося, Налаштування показують помилку й зберігають попередні параметри.",
    profiles: "Профілі зберігають колірну схему, вигляд і режими обох панелей, позначення правою кнопкою й активні клавіатурні скорочення. Виберіть Dirlume, Far Manager, Total Commander або власний профіль. Перегляньте зміни й натисніть «Застосувати» або «Готово». Закриття налаштувань скасовує незастосовані зміни.\n\n«Зберегти поточні налаштування як профіль» зберігає поточну конфігурацію. «Дублювати профіль» копіює збережений профіль. Після зміни налаштувань профіль має позначку «Змінено». Оновіть власний профіль або застосуйте його повторно. Під час перемикання можна зберегти зміни, відкинути їх або скасувати дію. Видалення профілю зберігає поточні налаштування. Якщо колірна схема відсутня, профіль показує вбудовану схему для заміни. Скорочення профілю можна змінити в розділі [[shortcuts|Клавіатурні скорочення]] під назвою «Скорочення поточних налаштувань».",
    appearance: "У розділі Вигляд → [[window|Вікно]] можна вибрати активну колірну схему, створити власну або задати улюблені схеми для системного режиму. Перегляд показує зміни кольорів і шрифтів під час редагування. Натисніть Застосувати, щоб побачити їх у головному вікні.",
    window: "Налаштуйте тло головного вікна й панелі інструментів, текст, рамки та колір фокусу. Клацніть зразок, щоб вибрати колір, або введіть його HEX-код. Кнопка скидання поряд із кольором повертає значення базової теми. Зніміть прапорець Показувати рядок стану, щоб звільнити місце. Ручка зміни розміру залишається внизу праворуч. Підтвердження дій з’являються на короткий час, а помилки залишаються, доки ви їх не закриєте.",
    panels: "Налаштуйте кольори [[files|тла файлових панелей]], назв, відомостей, піктограм папок і виділення в активній та неактивній панелі. Оцініть їх разом у зразку панелі. Увімкніть Приховати піктограми кнопок дій у Налаштуваннях → Основні файлові панелі, щоб показувати текст на панелі дій у всіх виглядах.",
    fileTypes: "Редагуйте стандартні групи розширень або створіть власну групу зі своїм кольором і шрифтом. Введіть розширення й натисніть «Додати розширення», щоб призначити його групі. Якщо розширення вже належить іншій групі, у налаштуваннях з’явиться її назва. Натисніть «Перенести розширення», підтвердьте перенесення, а потім натисніть «Застосувати» або «Готово». Враховується останнє розширення без урахування регістру. Приховані й системні елементи використовують кольори своїх атрибутів. Видимість налаштовується в розділі [[files|Основні файлові панелі]].",
    dialogs: "Налаштуйте тло діалогів, заголовки, текст, кольори помилок і кнопки. У попередньому перегляді можна оцінити, як текст і елементи керування виглядають на вибраному тлі.",
    textTools: "Задайте шрифт і кольори тла, тексту, виділення та змін для [[compare|порівняння файлів]]. Спільні кольори тексту й синтаксису залишаються типовими для [[editor|редактора]], [[viewer|переглядача]] й [[terminal|термінала]]. Налаштування шістнадцяткового переглядача, Markdown і командного рядка є на відповідних сторінках. Скиньте окреме поле, щоб відновити успадкування.",
    fonts: "Виберіть гарнітуру й розмір шрифту головного вікна, файлових панелей, діалогів файлових панелей, вікна параметрів і текстових інструментів. Обидві групи шрифтів діалогів також доступні в розділі [[dialogs|Вигляд → Діалоги]]. Введіть частину назви для пошуку серед встановлених шрифтів або виберіть гарнітуру зі списку.",
    viewFonts: "Наведіть вказівник на головне вікно, файлову панель, закладки папок або інший діалог файлової панелі, параметри, [[terminal|термінал]], командний рядок, [[compare|порівняння файлів]] чи документ. Скористайтеся Ctrl і коліщатком миші, щоб змінити розмір тексту. Споріднені діалоги мають спільний розмір. Змініть або вимкніть це скорочення в налаштуваннях клавіш. Тут відображаються зміни, зроблені скороченням із коліщатком миші. Вони зберігаються після перезапуску. Скиньте окремий розмір, щоб успадкувати його з налаштувань відповідного шрифту.",
    shortcuts: "У діалогах використовуйте клавіші зі стрілками, щоб переміщати фокус між доступними кнопками дій в одній групі. Натисніть Enter або пробіл, щоб активувати кнопку у фокусі. Щоб переходити між усіма елементами керування, використовуйте Tab і Shift+Tab. У полі редагування тексту ці комбінації вставляють табуляцію та зменшують відступ. Див. [[editor|Редактор]]. Натисніть Alt і підкреслену літеру в підписі або на кнопці, щоб перевести фокус на відповідний елемент керування. Якщо кілька елементів мають однакову літеру, натисніть її повторно, щоб перейти до наступного. F9 відкриває головне меню.\n\nВиберіть схему клавіатурних скорочень у налаштуваннях. Кнопка Нова схема копіює вибрану схему. Щоб додати прив’язку, натисніть Додати скорочення. Щоб замінити її, клацніть саму прив’язку, а щоб видалити, натисніть ×. Під час додавання або заміни скорочення прапорець під полем введення дозволяє розрізняти лівий і правий Ctrl. Кнопка Відновити стандартні скидає вибрану користувацьку схему. У довідці наведено стандартні комбінації.\n\nСкористайтеся полем «Пошук у довідці», щоб знайти назву або фразу в усій довідці без інтернету. Виберіть результат, щоб перейти до відповідного уривка. Очистіть пошук, щоб повернутися до змісту.",
  },
  ru: {
    ...controlHelpText.ru,
    terminalShortcuts: "Пока фокус находится в оболочке, она получает нажатия клавиш, включая сочетание, настроенное для копирования файлов. Оболочка обрабатывает нажатие сама, поэтому копирование файлов не запускается. Нажмите на файловую панель, чтобы снова использовать её сочетания. Если панели скрыты, нажмите «Терминал», чтобы вернуться к файлам. О командах и истории читайте в [[terminal|справке терминала]].",
    archives: "Пакеты Dirlume включают 7-Zip для работы с архивами без интернета. Выберите локальные файлы или папки и нажмите Shift+F1, затем укажите формат, путь назначения и параметры сжатия. Нажмите Enter на архиве, чтобы открыть его в [[files|файловой панели]]. F5 распаковывает выбранные элементы. Чтобы скопировать или переместить локальные элементы в папку ZIP или 7z с доступом на запись, нажмите F5 или F6 в другой панели и подтвердите архив и путь в нём. Просматривайте архив в режиме списка или дерева. В ZIP или 7z с доступом на запись F7 создаёт папку, Shift+F4 создаёт текстовый файл, а Файлы → Переименовать меняет имя выбранного элемента. В дереве новые элементы создаются в выбранной папке или в папке, содержащей выбранный файл. В архивах с доступом на запись F6 перемещает элементы в локальную папку или папку архива с доступом на запись. Элемент удаляется из архива после завершения копирования. F4 редактирует текстовые файлы, а F8 удаляет элементы. Зашифрованные и многотомные архивы открываются только для чтения. Профили сохраняют настройки архивации без паролей. Чтобы восстановить файл после архивации, скопируйте его из корзины в нужную папку. Системная команда восстановления может указывать на временную папку, в которой проверялся файл.",
    files: "Просматривайте папки независимо в двух панелях. В Ubuntu нажмите Enter на локальном исполняемом файле .sh, чтобы запустить его во встроенном терминале из папки скрипта. Клавишу действия Открыть можно изменить в Настройки → Сочетания клавиш. Для обычного открытия файла используйте двойной щелчок или действие Открыть в системе. Чтобы открыть папку, введите путь в поле адреса и нажмите Enter. Для [[operations|выбора нескольких элементов]] используйте Insert, Shift со стрелками или Ctrl и щелчок. Перетаскивайте разделитель, чтобы изменить ширину панелей. Режим отображения выбирайте в меню Левая или Правая. Столбцы и строку состояния можно изменить в Настройки → Режимы панелей. Ctrl+F12 открывает меню сортировки активной панели, а F4 в этом меню меняет дополнительные критерии. Щёлкните заголовки правой кнопкой, чтобы выбрать видимые столбцы. В разделе Настройки → Основные файловые панели меняются видимость скрытых файлов, [[panels|цвета]] и размер шрифта каждой панели. Ctrl+Shift+0–9 добавляет текущую папку в группу закладок, а правый Ctrl+0–9 открывает эту группу. Управляйте группами через Команды → Закладки папок. В параметре Вид панелей выберите Стандартный, Сдвоенные панели или Классический коммандер. Сдвоенные панели добавляют кнопки дисков с иконками, свободное место диска над каждым списком и плоскую панель клавиш. Классический коммандер использует плотные строки, панель дисков над каждой панелью, сведения о текущем элементе внизу и панель функциональных клавиш.\n\nКогда вы открываете локальный файл в назначенной системой программе, панель показывает состояние запроса, затем подтверждает его передачу или сообщает об ошибке. Путь и результат можно посмотреть в разделе [[terminal|Терминал → Открытия файлов]].\n\nОткройте файловое меню для одного файла и выберите подменю Git. В нём отображаются доступные для файла действия «Показать историю», «Показать авторство строк», «Сравнить с ревизией» и «Показать различия». Подготовленные и неподготовленные изменения показаны отдельно. Закрытие Git View возвращает к файлу. Сочетание можно изменить в разделе «Параметры → Сочетания клавиш».",
    operations: "Отметьте нужные элементы или оставьте курсор на одном из них. Копирование или перемещение открывает диалог с путём назначения, обычно из [[files|другой панели]]. Когда F6 открывает диалог перемещения с заполненным путём, фокус находится на кнопке Переместить. Нажмите Enter для перемещения по этому пути или перейдите к полю пути с помощью Tab или Shift+Tab и отредактируйте его. Следите за ходом операции и выбирайте, как обрабатывать существующие файлы или папки, когда появится запрос. Перетащите отмеченные элементы в другую локальную панель для копирования или выберите Переместить вместо копирования. Системный буфер обмена позволяет передавать локальные файлы между приложениями.\n\nПанель действий открывает просмотр, редактор, копирование, переименование или перенос, создание файлов и папок, корзину, сравнение, отметку и терминал в зависимости от режима и источника. Неактивная кнопка означает, что текущий элемент или вид не поддерживает действие. Когда отметка правой кнопкой отключена, короткое нажатие правой кнопкой в файловой панели открывает меню Dirlume. Для локального элемента в Windows удерживайте правую кнопку полсекунды и отпустите после появления индикатора, чтобы открыть системное меню. В Ubuntu и для источников без системного меню удержание открывает меню Dirlume. Сочетание Открыть контекстное меню файлов, по умолчанию Shift+F10, открывает меню Dirlume для текущей строки. Меню отмеченной строки показывает групповые действия и число элементов. Меню неотмеченной строки действует на этот элемент и сохраняет предыдущие отметки. Те же клавиши и диалоги доступны в [[search|результатах локального поиска]] для копирования, перемещения, корзины и окончательного удаления. См. [[actionDialogs|диалоги файловых операций]].\n\nЕсли при копировании или перемещении папка уже существует, Dirlume продолжает внутри неё и сохраняет элементы, которые есть только в месте назначения. В режиме «Спрашивать» подтверждение появляется при конфликтах файлов. «Перезаписать все» действует на все файлы текущей операции, которые можно перезаписать. Если включён запрос для файлов только для чтения, сохранённый для них выбор применяется только к ним. Сохранённый выбор для обычных файлов не отменяет отдельный запрос. Если в другой панели открыта папка коллекции, F5 добавляет в неё ссылки. F5 из коллекции копирует выбранные оригиналы. Команда «Удалить из коллекции» удаляет ссылки или виртуальные папки.\n\nДля одного выбранного элемента введите новое имя в поле назначения диалога F6, чтобы переименовать элемент в текущей папке. Другая панель подставляет начальный путь. Введите нужный путь назначения, чтобы переместить элемент в локальную папку или подключённый источник. Путь Google Drive включает подключённый аккаунт, :/Мой диск и путь к папке.",
    search: "В файловой панели удерживайте Alt и введите букву, чтобы открыть быстрый поиск. Он ищет в любой части имён видимых файлов и папок. Имена, начинающиеся с введённого текста, показываются первыми. Перебирайте совпадения стрелками вверх и вниз. Нажмите на число совпадений или нажмите Tab и Enter, чтобы открыть таблицу результатов. Выбор строки перемещает курсор к элементу и возвращает фокус в панель. В поле поиска Enter открывает текущее совпадение, а Esc возвращает фокус в панель. Команду «Быстрый поиск по имени» можно изменить или отключить в Настройки → Сочетания клавиш. Для поиска во вложенных папках откройте Найти файлы и введите маску, например *.md. Выберите Показать на панели, чтобы открыть совпадения в [[files|файловой панели]], или Перейти к выбранному файлу, чтобы открыть его папку.\n\nСтрока «Папка и вложенные папки» показывает корень поиска. В маске файла * соответствует любому числу символов, а ? — одному символу. Остановка сохраняет найденные совпадения. Частичный результат означает, что часть области осталась непроверенной. Переход к файлу показывает текущий результат, а показ в панели оставляет список в файловой панели. Закрытие завершает поиск.\n\nВ результатах локального поиска можно копировать, перемещать, отправлять в корзину или окончательно удалять отмеченные файлы или текущий файл. Успешно перемещённые или удалённые файлы исчезают из списка. Команда «Обновить» повторяет поиск с исходной папкой, маской и параметром скрытых файлов. Панель остаётся открытой даже при отсутствии совпадений. См. [[paneFilter|фильтр текущей папки]].",
    viewer: "Нажмите F3, чтобы просмотреть файл или измерить размер папки. В строке родительской папки (..) клавиша F3 и кнопка «Измерить» подсчитывают размеры видимых непосредственных дочерних папок, включая неотмеченные. В дереве раскрытые потомки учитываются в размере папки верхнего уровня. Настройка «Размеры папок» сохраняется. Escape останавливает оставшиеся вычисления и сохраняет готовые результаты. Чтобы просмотреть журнал, выберите Справка → Открыть журнал ошибок. В меню Файл этого просмотрщика выберите «Очистить журнал ошибок» и подтвердите удаление записей. Текстовые файлы размером более 8 МиБ открываются по страницам. Используйте стрелки или введите номер страницы и нажмите Enter, чтобы перейти к любой части файла. F4 в просмотрщике переключает шестнадцатеричный режим только для чтения. Прокручивайте весь файл или перейдите к смещению по десятичному или шестнадцатеричному адресу байта. Просмотр Markdown отображает диаграммы Mermaid и поддерживает ссылки между документами. Щёлкните по ссылке Markdown с Ctrl или Command на macOS, чтобы открыть отдельную вкладку. При открытии Markdown широкие диаграммы Mermaid по умолчанию вписываются в ширину области чтения даже с сохранённым увеличенным размером текста. Диаграммы меньшего размера сохраняют исходный размер. Задайте постоянный масштаб в разделе Настройки → Просмотрщик → Диаграммы Mermaid. Перетаскивайте широкую диаграмму мышью влево или вправо либо используйте ползунок горизонтальной прокрутки. Он остаётся видимым при просмотре диаграммы. Высокие диаграммы прокручиваются вертикально вместе с документом. Ctrl с колёсиком масштабирует текст и все диаграммы вместе. Наведите указатель на панель диаграммы или переведите фокус на кнопку, чтобы выделить элементы управления. Кнопки изменения и сброса масштаба действуют только на эту диаграмму. Нажмите «Вместить по горизонтали», чтобы увидеть оба её края одновременно. Команда «Открыть в новом окне» открывает диаграмму в текущем масштабе в независимом окне. Можно продолжить чтение и открывать другие диаграммы. Масштабируйте и перетаскивайте диаграмму в каждом окне или нажмите «Вписать», чтобы увидеть её целиком. Действие колёсика можно изменить или отключить в настройках сочетаний. В разделе Настройки → Просмотрщик задаются шрифт и отдельные размеры текста и Markdown. В текстовом просмотрщике путь к файлу расположен справа в строке меню, перед индикаторами состояния. Наведите указатель, чтобы увидеть полный путь, и нажмите «Копировать путь к файлу», чтобы скопировать его. После закрытия текстового файла фокус возвращается к панели или документу, из которого его открыли. Если этот документ уже закрыт, фокус возвращается к файловым панелям.\n\nВ текстовых режимах, включая исходный текст Markdown и файлы со страницами, выберите Отображение → Показать пробельные символы, чтобы увидеть пробелы и табуляцию. Общая ширина табуляции задаётся в Настройки → Просмотрщик или Настройки → Редактор. Стандартная ширина составляет четыре столбца и действует даже со скрытыми метками. Обе настройки сохраняются и не меняют скопированный или сохранённый текст.\n\nВ текстовом просмотрщике меню «Файл» содержит команды «Открыть в редакторе» для редактируемых файлов и «Закрыть». В меню «Навигация» доступен «Поиск» в оформленном Markdown и «Hex» в режимах исходного текста и шестнадцатеричного просмотра. В меню показаны настроенные сочетания клавиш. Поиск в документе находит текст, стрелки переходят между совпадениями, а счётчик показывает номер и число. В Markdown «Назад» и «Вперёд» переходят между открытыми ссылками. Просмотр и источник переключают оформление и текст. Форматирование HTML меняет вид источника. Журнал диагностики показывает раскрываемые записи или исходные строки.\n\nДля изображений кнопки предыдущего и следующего файла следуют порядку исходной панели и неактивны на краях. «Уместить» показывает всё изображение, 100% — фактические пиксели, а процент — текущий масштаб. Перетаскивание смещает увеличенное изображение. Hex показывает байты. Редактор доступен для редактируемых файлов. Закрытие возвращает к панели или предыдущему документу. Чтобы изменить цвет заголовка, откройте Настройки → Внешний вид → Окно и выберите «Заголовок документа».\n\nВ [[gitView|Git View]] выберите «Показать авторство строк», чтобы просмотреть авторов сохранённого в Git файла. В заголовке указаны ревизия и путь. Нажмите автора рядом со строкой, чтобы открыть коммит. «К строке» возвращает на прежнюю позицию. При переносе строк авторство остаётся рядом с текстом.",
    editor: "Нажмите F4 на текстовом файле, чтобы отредактировать его, или Shift+F4, чтобы создать файл и начать редактирование. Когда фокус находится в редактируемом тексте, Tab вставляет символ табуляции, а Shift+Tab уменьшает отступ текущей или выбранных строк на один уровень. Измените или отключите эти сочетания в Параметры → Сочетания клавиш. Ctrl+M (Alt+Shift+M в macOS) переключает навигацию фокусом с помощью Tab при редактировании. Текстовые файлы размером более 8 МиБ открываются по страницам. Можно изменить несколько страниц и сохранить все правки вместе. Если файл изменился вне Dirlume, откройте его снова перед сохранением. При необходимости выберите язык подсветки вручную. Сохраните файл перед закрытием или нажмите Esc. При наличии несохранённых изменений появится запрос. Для переключения между редакторами, [[viewer|просмотрщиками]] и [[files|файловыми панелями]] используйте панель открытых документов. В разделе Настройки → Редактор задаётся шрифт редактора. В текстовом редакторе путь к файлу расположен справа в строке меню. Наведите указатель, чтобы увидеть его полностью. Нажмите «Копировать путь к файлу», чтобы скопировать его. Переключение между просмотрщиком и редактором сохраняет место возврата. После закрытия файла фокус возвращается к панели или документу, из которого его открыли.\n\nВ текстовых режимах, включая исходный текст Markdown и файлы со страницами, выберите Отображение → Показать пробельные символы, чтобы увидеть пробелы и табуляцию. Общая ширина табуляции задаётся в Настройки → Просмотрщик или Настройки → Редактор. Стандартная ширина составляет четыре столбца и действует даже со скрытыми метками. Обе настройки сохраняются и не меняют скопированный или сохранённый текст.\n\nЛокальные PNG и JPEG можно поворачивать и обрезать. Настройте прямоугольник и пропорцию обрезки, затем примените изменение. Отмена и повтор переходят между изменениями. Масштаб и вписывание меняют просмотр. Сохранение копии пишет отдельный файл, замена оригинала требует подтверждения. При закрытии можно продолжить редактирование или отбросить изменения. Если текстовый файл изменился на диске, можно сохранить черновик или перечитать файл. Чтобы изменить цвет заголовка, откройте Настройки → Внешний вид → Окно и выберите «Заголовок документа».",
    terminal: "В локальной файловой панели нажмите F2 или откройте Команды → Меню пользователя. В Настройки → Сочетания клавиш можно отдельно настроить Открыть меню пользователя и Переименовать. Чтобы переименовать выбранный элемент, откройте Файлы → Переименовать. Меню запоминает рабочую папку, текущий элемент и отмеченные пути при открытии. В поле Источник меню можно переключиться между меню текущей папки, родительской папки и личным меню. Выберите Новая команда или Редактировать, заполните Имя и Команды оболочки и нажмите Сохранить команду, чтобы вернуться в то же меню. Вставить значение добавляет пути панелей, значения текущего или отмеченных элементов либо параметр запуска. Вставляйте значения на место аргументов без дополнительных кавычек. Горячая клавиша, условие видимости, маска имени и параметры запуска доступны в Дополнительные параметры. Включите Показать скрытые пункты, чтобы найти отфильтрованные команды. В Управлять меню можно упорядочивать команды, подменю и разделители. Стрелки Вверх и Вниз выбирают пункт, Вправо открывает подменю, Влево или Escape возвращают назад. Чтобы запустить команду, нажмите Выполнить, Enter или её горячую клавишу. Меню папок используют .dirlume-menu.json. Перед одобрением на текущий сеанс просмотрите содержимое. После изменения файла требуется новое одобрение. Команды выполняются в отдельном локальном сеансе оболочки и останавливаются при ошибке или после нажатия Остановить. Вывод и код завершения доступны в Терминале. Выполненные шаги могут оставить изменения.\n\nНажмите Терминал рядом с командной строкой, чтобы открыть интерактивную оболочку. Когда фокус на строке .. в локальной панели или панели SSH, команда «Вставить выбранный путь в командную строку» вставляет путь текущей папки. Enter на этой строке открывает родительскую папку. В поддерживаемых оболочках рабочая папка следует за активной локальной или [[remote|SSH-панелью]] после возврата к приглашению. Для однострочной команды выберите подсказку стрелками, вставьте её клавишей Tab или закройте список клавишей Esc. Enter вставляет выбранную подсказку или запускает команду, если ничего не выбрано. В Windows введите префикс сниппета KSwitcher, например `;`, в строке поддерживаемой оболочки. Tab вставляет выбранный однострочный сниппет. Команду можно редактировать до нажатия Enter. Сниппеты с клавиатурными действиями или паузами недоступны. Когда активна панель Linux по SSH, командная строка предлагает команды и пути с удалённого сервера ещё до открытия терминала. Подсказки в SSH-терминале учитывают окружение оболочки. Когда вы возвращаетесь из другой панели к открытому SSH-терминалу, подсказки по-прежнему учитывают папку и окружение этого сеанса. После пробела SSH-терминал Linux может показать параметры Bash вместе с другими подсказками. Введите - или --, чтобы отфильтровать параметры по имени. После отдельного аргумента -- поиск параметров прекращается. При выборе папки добавляется косая черта и появляются подсказки из её содержимого. В Windows и Linux подсказки учитывают установленные правила дополнения команды. Чтобы запросить подсказки файлов и папок там, где разрешено дополнение путей, начните путь, например, с ./. В Windows и Linux, в том числе в сеансах SSH с Linux, оба поля подсказывают подкоманды и параметры Docker. Введите пробел после команды, например docker ps или docker image ls, чтобы увидеть её параметры. Если параметру требуется значение, выберите подсказку от Docker или продолжите ввод. Имена и идентификаторы контейнеров зависят от контекста Docker, а имена сервисов Compose от проекта, выбранного рабочей папкой, параметром -f или переменной COMPOSE_FILE. [[files|Щёлкните файловую панель]], чтобы воспользоваться её сочетаниями клавиш.\n\nПравая кнопка мыши или Control-клик на macOS открывает меню с действиями «Копировать», «Вставить» и «Выбрать всё». Действие «Выбрать всё» включает сохранённый вывод за пределами экрана.\n\nКопируйте выделенный текст сочетанием Ctrl+Shift+C в Windows и Ubuntu или Command+C на macOS. Его можно изменить или отключить в Настройки → Сочетания клавиш. Над ссылкой HTTP или HTTPS меню также предлагает «Открыть ссылку» и «Копировать адрес ссылки». Для прямой вставки включите «Вставлять правой кнопкой мыши» в разделе Настройки → Терминал. Там же можно изменить шрифт и размер.\n\nКомандная строка запускает отдельную команду из показанной папки. Терминал поддерживает интерактивный сеанс. Заголовок показывает оболочку или соединение. Кнопка закрытия завершает сеанс. В Windows, если PowerShell завершился или не показал приглашение, нажмите «Перезапустить терминал», чтобы начать новый сеанс в активной локальной папке. Отправьте команды, оставшиеся в очереди, повторно. Разделитель меняет высоту, а настроенная команда скрывает или возвращает панели. Нажмите Alt+F8, чтобы открыть историю команд с датами и найти нужную команду. Команды отображаются моноширинным шрифтом с подсветкой синтаксиса, если оболочка известна. Выбор строки вернёт команду с переносами и отступами в командную строку для редактирования. Уведомление объясняет, когда вступят в силу изменения переменных среды. См. [[terminalShortcuts|приостановку файловых команд]].\n\nВыберите «Открытия файлов» в заголовке терминала, чтобы посмотреть время, путь и результат передачи запросов из обеих панелей. Здесь также видны попытки, сделанные при скрытом терминале. Раздел работает, когда оболочка занята или недоступна. Список очищается после перезапуска Dirlume.\n\nНовый локальный сеанс zsh открывается в папке активной панели. Эту папку показывают приглашение оболочки и заголовок терминала.\n\nПравая кнопка мыши или Control-клик на macOS открывает меню с действиями «Копировать», «Вставить» и «Выбрать всё». Действие «Выбрать всё» включает сохранённый вывод за пределами экрана.\n\nКопируйте выделенный текст сочетанием Ctrl+Shift+C в Windows и Ubuntu или Command+C на macOS. Его можно изменить или отключить в Настройки → Сочетания клавиш. Над ссылкой HTTP или HTTPS меню также предлагает «Открыть ссылку» и «Копировать адрес ссылки». Для прямой вставки включите «Вставлять правой кнопкой мыши» в разделе Настройки → Терминал. Там же можно изменить шрифт и размер.\n\nКомандная строка запускает отдельную команду из показанной папки. Терминал поддерживает интерактивный сеанс. Заголовок показывает оболочку или соединение. Кнопка закрытия завершает сеанс. В Windows, если PowerShell завершился или не показал приглашение, нажмите «Перезапустить терминал», чтобы начать новый сеанс в активной локальной папке. Отправьте команды, оставшиеся в очереди, повторно. Разделитель меняет высоту, а настроенная команда скрывает или возвращает панели. В истории команд с датами можно выбрать и повторно использовать прежнюю команду. Уведомление объясняет, когда вступят в силу изменения переменных среды. См. [[terminalShortcuts|приостановку файловых команд]].\n\nВыберите «Открытия файлов» в заголовке терминала, чтобы посмотреть время, путь и результат передачи запросов из обеих панелей. Здесь также видны попытки, сделанные при скрытом терминале. Раздел работает, когда оболочка занята или недоступна. Список очищается после перезапуска Dirlume.\n\nВ локальном терминале PowerShell или в командной строке Windows введите ipconfig /flushdns отдельной командой. Если системная программа Windows сообщит, что нужны права администратора, Windows запросит подтверждение. После согласия команда выполняется в отдельном процессе с повышенными правами, а результат появится в терминале. После отказа можно продолжить работу в том же терминале. Другие команды и сценарии выполняются как обычно.",
    compare: "Выберите по текстовому файлу в [[files|каждой панели]] или отметьте два файла в одной панели, затем откройте Сравнить файлы. На панели инструментов выберите Объединённый или Рядом. В режиме Рядом можно перетащить разделитель и показать связи между изменениями. Включите показ пробельных изменений, если важны отступы или пробелы в конце строк.\n\n«Предыдущая» и «Следующая» переходят между различиями. Применение влево или вправо переносит текущее изменение и недоступно без подходящего выбора. Свёрнутые неизменённые строки можно раскрыть. Сохранение спрашивает, какую сторону записать и следует ли заменить оригинал или создать копию. При закрытии с несохранёнными изменениями можно продолжить редактирование или отбросить их.",
    googleDrive: "Откройте Google Drive в источниках любой панели. Добавьте или заново подключите аккаунт и разрешите доступ в браузере. Нажмите Enter на подключении, чтобы открыть Мой диск. Переключайтесь между списком и деревом так же, как в локальных папках.\n\nНажмите Shift+F4 для нового текстового файла, F7 для новой папки, Файлы → Переименовать для смены имени, F3 для просмотра и F4 для редактирования поддерживаемых текстовых файлов. Выберите место назначения в другой панели и нажмите F5 для копирования или F6 для перемещения файлов и папок между Моим диском и компьютером или между папками на Диске. Нажмите F8, чтобы переместить выбранные элементы в корзину Google Drive. Окончательное удаление доступно в меню файлов. Нажмите F4 на файле Office или документе, таблице либо презентации Google, чтобы открыть его для редактирования в браузере. Google Drive применяет права подключенного аккаунта.\n\nВыберите папку и нажмите F3, чтобы вычислить её размер с учётом вложенных папок. Выберите «Размеры папок», чтобы вычислить размеры всех папок на текущем уровне. Частичный итог означает, что некоторые размеры недоступны.\n\nПри копировании или перемещении на локальный диск Google Docs, Sheets, Slides, Drawings и Apps Script экспортируются в DOCX, XLSX, PPTX, PDF и JSON. Элементы без доступного экспорта сохраняются как ссылки .url. При перемещении источники этих ссылок остаются в Drive. Если папка содержит такие ссылки, её источник в Drive сохраняется целиком.",
    remote: "Выберите NetBox в источниках любой панели или нажмите 2 в этом меню. NetBox показывает сохранённые подключения FTP, FTPS и SFTP с именем, протоколом и хостом. Нажмите Shift+F4, чтобы добавить профиль, F4 — чтобы изменить или Enter — чтобы подключиться. На странице «Сеанс» выберите протокол и проверьте подключение перед сохранением. Для FTP выберите подключение без шифрования, явный или неявный TLS. Стандартный порт обычного FTP и явного TLS — 21, неявного TLS — 990. Явный TLS включается до аутентификации, неявный — в начале подключения. Оба режима шифруют передачу файлов и списки папок и проверяют доверие к сертификату и его соответствие хосту. Если проверка не пройдена, подключение завершается ошибкой. Для нового профиля по умолчанию выбран SFTP (SSH). Выберите название страницы или воспользуйтесь стрелками справа. Сочетания Ctrl+PageUp и Ctrl+PageDown по умолчанию переключают доступные страницы. Изменить или отключить их можно в разделе «Настройки» → «Сочетания клавиш». NetBox сохраняет черновик при переключении страниц. На странице «Каталоги» задайте абсолютный путь к начальной папке или оставьте поле пустым для папки сервера по умолчанию. Если включено запоминание, NetBox сперва пробует последнюю успешно открытую папку. Закладки открывают сохранённый путь. «Назад» и «Вперёд» могут использовать кеш посещённых папок. Кеш переходов действует и при обычной навигации. Обновление всегда перечитывает сервер. Для SFTP можно определять цели символьных ссылок на папки. На странице «Среда» выберите окончания строк для файлов без переносов. Имеющиеся окончания и байты двоичных файлов сохраняются. Для FTP можно выбрать устаревшую кодировку имён и часовой пояс для меток LIST. Используйте фиксированное смещение от UTC либо местное время со смещением на дату файла или текущим смещением. Метки UTC используются без изменений. Сохранение времени изменения при скачивании задаёт это время для локальной копии. Обычный FTP передаёт пароли и файлы без шифрования. Сохранённый профиль FTP может открыть последнюю папку при запуске. В FTP и SFTP нажмите F7 для создания папки или Shift+F4 для создания и открытия текстового файла. Если SFTP откажет в файловой операции, Dirlume предложит продолжить с sudo для этого подключения. Это касается создания, переименования, передачи, удаления, просмотра изображений и шестнадцатеричных данных, быстрого просмотра и измерения папок. При передаче или удалении повторяется действие, в котором было отказано, а завершённые действия сохраняются. Нажмите F5 или F6, чтобы копировать или перемещать файлы и папки между локальными папками, FTP, FTPS, SFTP, общими папками Dirlume, папками KSwitcher LAN и архивами, которые разрешают нужное действие. Dirlume сохраняет оригинал до завершения записи копии.\n\nВ разделе Среда → Удалённая корзина выберите существующую папку по абсолютному пути на сервере и включите перемещение удалённых элементов. F8 или Delete перемещает элементы переименованием на сервере. В корзине каждый элемент хранится в отдельной папке с исходным путём. Чтобы восстановить элемент, переместите его обратно на сервере. Shift+Delete запрашивает подтверждение окончательного удаления. Если корзина недоступна или сервер отклоняет перемещение, Dirlume сообщает об ошибке. Для SFTP можно также сохранять предыдущие версии перезаписанных файлов.\n\nНа странице «FTP(S)» автоматический режим MLSD переключается на LIST, если сервер отклоняет MLSD. «Включено» требует MLSD, а «Выключено» использует LIST. В пассивном режиме соединение для данных открывает этот компьютер. В активном режиме сервер должен подключиться к порту этого компьютера. Пустое имя пользователя означает анонимный вход. Отправка пустого пароля сохраняет записанный пароль для дальнейшего использования. Команды после входа выполняются по порядку после аутентификации. Два параметра 0xFF независимо управляют обработкой байта в командах и ответах PWD для устаревших серверов.\n\nНа странице «Подключение» можно оставить время ожидания ответа по умолчанию, отключить его или задать от 1 до 3600 секунд. По умолчанию это 12 секунд для FTP и 15 секунд для SFTP. Для поддержания соединения FTP использует проверки TCP, а SFTP — сообщения SSH. Стандартный интервал SSH — 30 секунд. Автоматический режим использует доступные адреса, а IPv4 и IPv6 ограничивают прямое подключение соответствующей версией IP. В маршруте SSH через промежуточные узлы этот параметр применяется к первому узлу. Для FTP можно включить увеличенные буферы данных. Чтобы остановить проверку, нажмите «Отменить проверку» или Escape.\n\nНа странице «SFTP» оставьте команду сервера пустой для стандартной подсистемы. Укажите команду, если сервер запускает SFTP иначе. Включите знаковое время изменения для серверов, которые кодируют даты до 1970 года знаковыми 32-битными секундами. Клиент использует SFTP версии 3. На странице «Shell» выберите оболочку по умолчанию, Bash, Zsh или sh для терминала SSH.\n\nНа странице «Прокси» выберите SOCKS5 или HTTP CONNECT, укажите сервер прокси и при необходимости учётные данные. Пароль прокси хранится в системном хранилище учётных данных. Укажите, где разрешать имена серверов и подключаться ли к localhost и адресам loopback напрямую. FTP и FTPS через прокси используют пассивный режим. Для SSH и SFTP прокси подключается к первому промежуточному серверу, если он задан. Остальные переходы выполняет SSH. При отказе прокси Dirlume сообщает об ошибке настроенного маршрута.\n\nДля SSH и SFTP укажите конечный сервер и данные для входа. В разделе «Промежуточные SSH-серверы» нажмите «Добавить промежуточный сервер» для каждого перехода. Для каждого сервера укажите пароль или закрытый ключ и, при необходимости, парольную фразу. «Маршрут» показывает порядок серверов. Каждый промежуточный сервер должен разрешать перенаправление TCP к следующему. Кнопка «Проверить подключение» получает список файлов начальной папки конечного сервера. Сверьте отпечаток SHA-256 каждого нового сервера с его администратором. Подтверждение во время проверки действует только для этой проверки. При первом открытии сохранённого подключения нажмите «Доверять и подключиться». При изменении ключа подключение блокируется. Сохранённый маршрут также используется для передачи файлов, закладок папок и [[terminal|SSH-терминала]]. Если терминал неожиданно закрывается, Dirlume проверяет доступ по SFTP. При потере доступа панель возвращается к списку NetBox. Такой же результат возможен при открытии или обновлении папки. Выберите сохранённое подключение, чтобы войти снова. Обычный выход из оболочки оставляет файловую панель открытой.\n\nВыберите SMB в источниках любой панели в Windows, macOS или Ubuntu. Добавьте соединение по имени сервера, IP-адресу или адресу общего ресурса, например smb://server/documents. В Windows также доступны пути UNC. Откройте сервер, чтобы увидеть общие ресурсы. Из корня общего ресурса перейдите в родительскую папку, чтобы вернуться к серверу. При запросе введите данные для входа. Параметр «Запомнить учётные данные» сохраняет их в системном хранилище. В Ubuntu нужны пакеты GVfs для SMB и FUSE.\n\nВ удалённой папке нажмите имя источника в адресной строке, чтобы открыть список сохранённых подключений. Выберите приглушённый сегмент, чтобы вернуться к подключению или папке. «Назад» возвращает в ту же папку. Для сохранённого подключения к серверу Dirlume выберите «Удалённый компьютер». В Windows добавьте Dirlume.exe в список Trusted clients в окне компьютеров KSwitcher. Чтобы просмотреть файлы ПК, сопряжённого через KSwitcher, откройте его диск в разделе KSwitcher LAN. В KSwitcher 0.8.0 или новее на обоих ПК предоставьте Allow write для копирования, создания, переименования и сохранения правок, а Allow delete — для удалённой корзины и окончательного удаления. Для перемещения нужны оба разрешения. Копирование и перемещение между путями на одном сопряжённом ПК выполняются на нём. Если KSwitcher поддерживает запросы для отдельных конфликтов, выберите «Спрашивать». В других версиях можно остановиться при конфликте, пропускать элементы или перезаписывать все. Если связь пропала, проверьте, запущен ли KSwitcher на обоих компьютерах. Панель продолжит просмотр после восстановления связи. Чтобы повторить попытку сразу, обновите папку. Общие папки сервера Dirlume по умолчанию доступны для чтения. Выберите файл или папку и нажмите F5 для копирования в локальную папку. Если владелец запустил сервер с параметром --allow-write, можно также создавать, редактировать, переименовывать, перемещать и удалять элементы в списке или дереве и копировать их в общую папку. Действуют права файловой системы сервера. Если в месте назначения уже есть одноимённая папка, выберите действие для конфликтующих элементов. В Настройки → Компьютеры создайте группу Dirlume LAN на одном компьютере. Скопируйте код и присоединитесь с тем же кодом на остальных компьютерах. Откройте диск в разделе Dirlume LAN меню источников любой панели. Dirlume автоматически определяет имена компьютеров. Нажмите F5, чтобы копировать файлы и папки в Dirlume LAN или из него. Нажмите F6, чтобы переместить файлы и папки. Dirlume сохраняет исходные файлы и папки до завершения записи копии в месте назначения. В списке или дереве нажмите F7 для создания папки, Shift+F4 для создания текстового файла, F4 для редактирования, Файлы → Переименовать для смены имени или Delete для окончательного удаления. Владелец компьютера должен разрешить участникам группы изменять файлы и папки. После перезапуска Dirlume снова присоединяется к сохранённой группе, когда локальная сеть доступна. Изначально разрешено только чтение. Команда «Выйти из группы» прекращает доступ и удаляет сохранённую группу. Старые коды сопряжения доступны для предыдущих версий Dirlume.",
    processes: "Откройте источники панели и выберите Процессы или нажмите 0. Щёлкните по заголовку столбца для сортировки. Удерживайте Alt и введите букву, чтобы открыть [[search|быстрый поиск]] по имени процесса. Выберите одну или несколько строк и нажмите F8, чтобы открыть подтверждение завершения процессов.",
    general: "Выберите язык интерфейса и [[remote|провайдера для кнопки Подключить]]. В Windows при выборе KSwitcher можно указать папку установки. Версия показывает номер установленной сборки. Поле Поиск настроек находит разделы и отдельные параметры. Кнопка [[appearance|Выбрать элемент]] открывает настройки оформления выбранного элемента. Esc возвращает на ту же страницу. История выбора хранит выбранные элементы по датам. Применить сохраняет изменения и оставляет окно открытым, а Готово сохраняет и закрывает его.\n\nИмпорт настроек позволяет выбрать группы и цветовые схемы из архива. Экспорт записывает выбранные группы и схемы. «Применить» доступно после допустимого изменения, «Готово» недоступно при неверных данных. Если есть кнопка отмены, она закрывает диалог без применения черновика. См. [[shortcuts|схемы клавиш]] и [[appearance|оформление]].\n\nВ Windows обычный запуск и запуск от имени администратора одной копии используют dirlume-settings.json рядом с Dirlume.exe. После обновления один раз откройте Dirlume обычным способом, чтобы перенести старые параметры в папку приложения, если она доступна для записи. Если папка защищена от записи, воспользуйтесь командой «Открыть от имени администратора» в обычном окне Dirlume, чтобы создать файл настроек. Если сохранить изменения не удалось, Настройки покажут ошибку и сохранят прежние параметры.",
    profiles: "Профили сохраняют цветовую схему, вид и режимы обеих панелей, отметку правой кнопкой и действующие сочетания клавиш. Выберите Dirlume, Far Manager, Total Commander или свой профиль. Просмотрите изменения и нажмите «Применить» или «Готово». Закрытие настроек отменяет неприменённые изменения.\n\n«Сохранить текущие настройки как профиль» сохраняет текущую конфигурацию. «Дублировать профиль» копирует сохранённый профиль. Изменённый профиль помечается как «Изменён». Обновите свой профиль или примените его повторно. При переключении можно сохранить изменения, отбросить их или отменить действие. Удаление профиля сохраняет текущие настройки. Если цветовая схема отсутствует, профиль показывает встроенную схему для замены. Сочетания профиля можно редактировать в разделе [[shortcuts|Сочетания клавиш]] под названием «Сочетания текущих настроек».",
    appearance: "В разделе Внешний вид → [[window|Окно]] можно выбрать активную цветовую схему, создать свою или задать избранные схемы для системного режима. Предпросмотр показывает изменения цветов и шрифтов при редактировании. Нажмите Применить, чтобы увидеть их в главном окне.",
    window: "Настройте фон главного окна и панели инструментов, текст, рамки и цвет фокуса. Щёлкните по образцу, чтобы выбрать цвет, или введите его HEX-код. Кнопка сброса рядом с цветом возвращает значение базовой темы. Снимите флажок Показывать строку состояния, чтобы освободить место. Ручка изменения размера остаётся внизу справа. Подтверждения действий появляются ненадолго, а ошибки остаются, пока вы их не закроете.",
    panels: "Настройте цвета [[files|фона файловых панелей]], имён, сведений, значков папок и выделения в активной и неактивной панелях. Оцените их вместе в образце панели. Включите Скрыть значки кнопок действий в Настройках → Основные файловые панели, чтобы показывать текст на панели действий во всех видах.",
    fileTypes: "Редактируйте стандартные группы расширений или создайте свою группу со своим цветом и шрифтом. Введите расширение и нажмите «Добавить расширение», чтобы назначить его группе. Если расширение уже относится к другой группе, в настройках появится её название. Нажмите «Перенести расширение», подтвердите перенос, а затем нажмите «Применить» или «Готово». Учитывается последнее расширение без учёта регистра. Скрытые и системные элементы используют цвета своих атрибутов. Видимость настраивается в разделе [[files|Основные файловые панели]].",
    dialogs: "Настройте фон диалогов, заголовки, текст, цвета ошибок и кнопки. В предварительном просмотре можно оценить, как текст и элементы управления выглядят на выбранном фоне.",
    textTools: "Задайте шрифт и цвета фона, текста, выделения и изменений для [[compare|сравнения файлов]]. Общие цвета текста и синтаксиса остаются значениями по умолчанию для [[editor|редактора]], [[viewer|просмотрщика]] и [[terminal|терминала]]. Настройки шестнадцатеричного просмотра, Markdown и командной строки находятся на соответствующих страницах. Сбросьте отдельное поле, чтобы восстановить наследование.",
    fonts: "Выберите гарнитуру и размер шрифта главного окна, файловых панелей, диалогов файловых панелей, окна параметров и текстовых инструментов. Обе группы шрифтов диалогов также доступны в разделе [[dialogs|Внешний вид → Диалоги]]. Введите часть названия для поиска среди установленных шрифтов или выберите гарнитуру из списка.",
    viewFonts: "Наведите указатель на главное окно, файловую панель, закладки папок или другой диалог файловой панели, параметры, [[terminal|терминал]], командную строку, [[compare|сравнение файлов]] или документ. Используйте Ctrl и колёсико мыши, чтобы изменить размер текста. Связанные диалоги используют общий размер. Измените или отключите сочетание в настройках клавиш. Здесь отображаются изменения, сделанные сочетанием с колёсиком мыши. Они сохраняются после перезапуска. Сбросьте отдельный размер, чтобы унаследовать его из настроек соответствующего шрифта.",
    shortcuts: "В диалогах используйте клавиши со стрелками, чтобы перемещать фокус между доступными кнопками действий в одной группе. Нажмите Enter или пробел, чтобы активировать кнопку в фокусе. Для перехода между всеми элементами управления используйте Tab и Shift+Tab. В поле редактирования текста эти сочетания вставляют табуляцию и уменьшают отступ. См. [[editor|Редактор]]. Нажмите Alt и подчёркнутую букву в подписи или на кнопке, чтобы перевести фокус на соответствующий элемент управления. Если буква назначена нескольким элементам, нажмите её повторно, чтобы перейти к следующему. F9 открывает главное меню.\n\nВыберите схему сочетаний клавиш в настройках. Кнопка Новая схема копирует выбранную схему. Чтобы добавить сочетание, нажмите Добавить сочетание. Чтобы заменить его, щёлкните по самому сочетанию, а чтобы удалить, нажмите ×. При добавлении или замене сочетания флажок под полем ввода позволяет различать левый и правый Ctrl. Кнопка Восстановить значения по умолчанию сбрасывает выбранную пользовательскую схему. В справке указаны стандартные сочетания.\n\nВоспользуйтесь полем «Поиск по справке», чтобы найти название или фразу во всей справке без интернета. Выберите результат, чтобы перейти к нужному фрагменту. Очистите поиск, чтобы вернуться к оглавлению.",
  },
};
